import{d as c,C as r,o as q,c as j,j as n,a as e,E as t,a3 as f}from"./chunks/framework.D4-ViStF.js";const C=JSON.parse('{"title":"庄子·德充符","description":"借形残、貌丑与庄惠之辩，理解庄子所说内在充盈的生命状态。","frontmatter":{"title":"庄子·德充符","description":"借形残、貌丑与庄惠之辩，理解庄子所说内在充盈的生命状态。","category":"guide","aliases":["德充符","庄子德充符","zhuangzi chapter 05"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-05.md","filePath":"daoism/zhuang-zi/chapter-05.md","lastUpdated":1788516578000}'),k={name:"daoism/zhuang-zi/chapter-05.md"},D=c({...k,setup(P){const y=[{id:"wangtai_s1",label:"鲁有兀者王骀……丘将引天下而与从之",sentences:[["鲁有",{text:"兀者",glossary:"wu_zhe"},{text:"王骀",glossary:"wang_tai"},"，从之游者与仲尼",{text:"相若",glossary:"xiang_ruo"},"。"],["常季问于仲尼曰：「王骀，兀者也，从之游者与夫子",{text:"中分鲁",glossary:"zhong_fen_lu"},"。",{text:"立不教",glossary:"li_bu_jiao"},"，",{text:"坐不议",glossary:"zuo_bu_yi"},"。",{text:"虚而往",glossary:"xu_er_wang"},"，",{text:"实而归",glossary:"shi_er_gui"},"。"],["固有",{text:"不言之教",glossary:"buyan_zhijiao"},"，",{text:"无形而心成者",glossary:"wuxing_xincheng"},"邪？是何人也？」"],["仲尼曰：「夫子，圣人也，丘也",{text:"直",glossary:"zhi_buguo"},{text:"后",glossary:"hou_luohou"},"而",{text:"未往",glossary:"wei_wang"},"耳！"],["丘将以为师，而况不若丘者乎！",{text:"奚",glossary:"xi_hebi"},{text:"假",glossary:"jia_juxian"},"鲁国，丘",{text:"将",glossary:"jiang_jiangyao"},{text:"引",glossary:"yin_lingdao"},"天下",{text:"而与",glossary:"er_yu_yiqi"},"从之。」"]]},{id:"wangtai_s2",label:"常季曰彼兀者也……命物之化而守其宗也",sentences:[["常季曰：「",{text:"彼",glossary:"bi_ta"},"兀者也，而",{text:"王先生",glossary:"wang_xiansheng"},"，其与",{text:"庸",glossary:"yong_pingchang"},"亦",{text:"远矣",glossary:"yuan_xiangyuan"},"。",{text:"若然者",glossary:"ruoran_zhe2"},"，",{text:"其用心也",glossary:"qi_yongxin"},"，",{text:"独若之何",glossary:"du_ruozhihe"},"？」"],["仲尼曰：「死生亦大矣，而不得与之",{text:"变",glossary:"bian_gaibian"},"；虽天地",{text:"覆坠",glossary:"fu_zhui"},"，亦将",{text:"不与之遗",glossary:"bu_yu_yi"},"；"],[{text:"审乎无假",glossary:"shen_wujia"},"而",{text:"不与物迁",glossary:"bu_yu_wuqian"},"，",{text:"命",glossary:"ming_shunying"},{text:"物之化",glossary:"wu_zhihua"},"而",{text:"守其宗也",glossary:"shou_qi_zong"},"。」"]]},{id:"wangtai_s3",label:"常季曰何谓也……视丧其足犹遗土也",sentences:[["常季曰：「何谓也？」仲尼曰：「",{text:"自其异者视之",glossary:"zi_yi_zhi"},"，",{text:"肝胆楚越也",glossary:"gan_dan_chuyue"},"；",{text:"自其同者视之",glossary:"zi_tong_zhi"},"，",{text:"万物皆一也",glossary:"wanwu_jieyi"},"。"],["夫若然者，且不知",{text:"耳目之所宜",glossary:"ermu_suoyi"},"，而",{text:"游心乎",glossary:"you_xin_hu"},{text:"德之和",glossary:"de_zhihe"},"。"],["物视其所",{text:"一",glossary:"yi_tongyi"},"而不见其所",{text:"丧",glossary:"sang_shishi"},"，视",{text:"丧其足",glossary:"sang_qi_zu"},{text:"犹",glossary:"you_ruotong"},{text:"遗土",glossary:"yi_tu"},"也。」"]]},{id:"wangtai_s4",label:"常季曰彼为己……物何为最之哉",sentences:[["常季曰：「",{text:"彼为己",glossary:"bi_wei_ji"},"，以其知得其心，以其心得其",{text:"常心",glossary:"chang_xin"},"。",{text:"物何为最之哉",glossary:"wu_zuizhi"},"？」"]]},{id:"wangtai_s5",label:"仲尼曰人莫鉴于流水……彼且何肯以物为事乎",sentences:[["仲尼曰：「人莫",{text:"鉴",glossary:"jian_jingzi"},"于",{text:"流水",glossary:"liu_shui"},"而鉴于",{text:"止水",glossary:"zhi_shui"},"。",{text:"唯止能止众止",glossary:"zhi_neng_zhi"},"。"],[{text:"受命于地",glossary:"shou_ming_di"},"，唯松柏",{text:"独也正",glossary:"du_ye_zheng"},"，在冬夏青青；"],["受命于天，唯尧、舜独也正，在万物之首。"],["幸能正生，以正众生。夫",{text:"保始之徵",glossary:"bao_shi_zheng"},"，不惧之实，勇士一人，雄入于九军。"],[{text:"将求名",glossary:"jiang_qiu_ming"},"而能",{text:"自要者",glossary:"zi_yao_zhe"},"，",{text:"而犹若是",glossary:"er_you_rushi"},"，而况",{text:"官天地",glossary:"guan_tiandi"},"、",{text:"府万物",glossary:"fu_wanwu"},"、直寓六骸、象耳目、一知之所知而心未尝死者乎！"],[{text:"彼",glossary:"bi_ta2"},{text:"且",glossary:"qie_jiangyao"},{text:"择日而登假",glossary:"ze_ri_dengjia"},"，人则从是也。",{text:"彼且何肯以物为事乎",glossary:"ken_yiwu_weishi"},"！」"]]}],d=[{id:"wu_zhe",term:"兀者",pinyin:"wù zhě",meaning:"被砍去一足的人、断足之人。兀：断足、残缺；者：的人。古代刑罚之一为刖刑（砍足），兀者即受过刖刑者。"},{id:"wang_tai",term:"王骀",pinyin:"wáng tái",meaning:"人名，庄子虚构的断足圣人。王：姓；骀：名，读 tái。虽形残，却德充，门徒众多，与孔子并列。"},{id:"xiang_ruo",term:"相若",pinyin:"xiāng ruò",meaning:"差不多、相当。相：互相；若：如、相当。从之游者与仲尼相若：跟随王骀的人与跟随孔子的人数量差不多。"},{id:"zhong_fen_lu",term:"中分鲁",pinyin:"zhōng fēn lǔ",meaning:"（与孔子）平分鲁国（的门徒）。中分：对半分、平分；鲁：鲁国。"},{id:"li_bu_jiao",term:"立不教",pinyin:"lì bù jiào",meaning:"站着不讲授（不主动教导）。立：站立；不教：不教导、不讲学。"},{id:"zuo_bu_yi",term:"坐不议",pinyin:"zuò bù yì",meaning:"坐着不议论（不发表言论）。坐：坐着；不议：不议论、不讨论。立不教·坐不议：两句对举，形容王骀完全不用言语教化，却门徒众多。"},{id:"xu_er_wang",term:"虚而往",pinyin:"xū ér wǎng",meaning:"（学生）空虚地前往（求学）。虚：内心空虚、没有所得；往：前往。"},{id:"shi_er_gui",term:"实而归",pinyin:"shí ér guī",meaning:"（学生）充实地归来。实：内心充实、有所得；归：归来。虚而往·实而归：去时空虚，回来充实——王骀以无言之教使人自得。"},{id:"buyan_zhijiao",term:"不言之教",pinyin:"bù yán zhī jiào",meaning:"不用言语的教化。不言：不用言辞；之教：的教化。呼应《道德经》「行不言之教」，是道家教化观的核心。"},{id:"wuxing_xincheng",term:"无形而心成者",pinyin:"wú xíng ér xīn chéng zhě",meaning:"没有（具体）形式却使内心有所成就的（人/道）。无形：没有具体形式；心成：内心有所成就、完成。"},{id:"zhi_buguo",term:"直",pinyin:"zhí",meaning:"只是、不过。副词，表限定。丘也直后而未往耳：我孔丘只是落后了还没有去（拜访他）罢了。"},{id:"hou_luohou",term:"后",pinyin:"hòu",meaning:"落后、迟了。直后而未往：只是迟了还没去（拜访）。"},{id:"wei_wang",term:"未往",pinyin:"wèi wǎng",meaning:"还没有前往（拜访）。未：尚未；往：前往。"},{id:"xi_hebi",term:"奚",pinyin:"xī",meaning:"何必、为什么。疑问副词。奚假鲁国：何必局限于鲁国。"},{id:"jia_juxian",term:"假",pinyin:"jiǎ",meaning:"局限于、借助于。奚假鲁国：何必局限在鲁国（一地）。【古今异义】假：借助、局限，非「假装」。"},{id:"jiang_jiangyao",term:"将",pinyin:"jiāng",meaning:"将要、打算。副词，表将来意图。"},{id:"yin_lingdao",term:"引",pinyin:"yǐn",meaning:"引领、带领。丘将引天下而与从之：我将引领天下人一起跟随他。"},{id:"er_yu_yiqi",term:"而与",pinyin:"ér yǔ",meaning:"一起、共同。而：连词；与：一起、共同。引天下而与从之：引领天下人一起跟随他。"},{id:"bi_ta",term:"彼",pinyin:"bǐ",meaning:"他、那个人。指示代词，指王骀。"},{id:"wang_xiansheng",term:"王先生",pinyin:"wàng xiān shēng",meaning:"超越先生（孔子）。王：超越、凌驾，读 wàng；先生：指孔子。⚠️ 王读 wàng，非「王者」，此处为动词「超越」。"},{id:"yong_pingchang",term:"庸",pinyin:"yōng",meaning:"平常、普通。其与庸亦远矣：他与普通人相差也太远了。"},{id:"yuan_xiangyuan",term:"远矣",pinyin:"yuǎn yǐ",meaning:"相差甚远。远：差距大；矣：感叹语气词。"},{id:"ruoran_zhe2",term:"若然者",pinyin:"ruò rán zhě",meaning:"像这样的人。若然：像这样；者：的人。"},{id:"qi_yongxin",term:"其用心也",pinyin:"qí yòng xīn yě",meaning:"他（王骀）用心（的方式）。用心：运用心智、内心的修养方式；也：助词，表停顿。"},{id:"du_ruozhihe",term:"独若之何",pinyin:"dú ruò zhī hé",meaning:"究竟是怎样的呢？独：究竟、到底；若之何：怎么样、如何。"},{id:"bian_gaibian",term:"变",pinyin:"biàn",meaning:"改变、动摇。死生亦大矣，而不得与之变：死生虽然是大事，却不能使他（的心）改变。"},{id:"fu_zhui",term:"覆坠",pinyin:"fù zhuì",meaning:"倾覆坠落、崩塌。覆：翻覆；坠：坠落。虽天地覆坠：即使天地崩塌。"},{id:"bu_yu_yi",term:"不与之遗",pinyin:"bù yǔ zhī yí",meaning:"也不会随之消亡（丧失）。与之：随着它；遗：丧失、消亡。亦将不与之遗：也不会随天地崩塌而消亡。"},{id:"shen_wujia",term:"审乎无假",pinyin:"shěn hū wú jiǎ",meaning:"明察于（万物）本无所凭借（皆自然而然）。审：明察、审视；乎：于；无假：无所凭借、不依赖外物。"},{id:"bu_yu_wuqian",term:"不与物迁",pinyin:"bù yǔ wù qiān",meaning:"不随外物的变化而迁移（内心不受外物左右）。与物：随着外物；迁：迁移、改变。"},{id:"ming_shunying",term:"命",pinyin:"mìng",meaning:"顺应、听任。动词，顺应（万物的变化）。命物之化：顺应万物的变化。"},{id:"wu_zhihua",term:"物之化",pinyin:"wù zhī huà",meaning:"万物的变化。物：万物；化：变化、变迁。"},{id:"shou_qi_zong",term:"守其宗也",pinyin:"shǒu qí zōng yě",meaning:"守住那（万物的）根本。守：守持；宗：根本、本源；也：语气词。命物之化而守其宗：顺应万物变化，同时守住根本——即以不变应万变。"},{id:"zi_yi_zhi",term:"自其异者视之",pinyin:"zì qí yì zhě shì zhī",meaning:"从（万物）相异的角度来看它（们）。自：从；异者：相异之处；视之：看待它们。"},{id:"gan_dan_chuyue",term:"肝胆楚越也",pinyin:"gān dǎn chǔ yuè yě",meaning:"（就像）肝与胆（虽近却）如楚国与越国（那样遥远）。肝胆：肝脏与胆囊，紧邻的器官；楚越：楚国与越国，相距遥远的两国。喻从差异角度看，近在咫尺也如天壤之别。"},{id:"zi_tong_zhi",term:"自其同者视之",pinyin:"zì qí tóng zhě shì zhī",meaning:"从（万物）相同的角度来看它（们）。同者：相同之处。"},{id:"wanwu_jieyi",term:"万物皆一也",pinyin:"wàn wù jiē yī yě",meaning:"万物都是同一的。皆一：都是一体、没有分别；也：判断语气词。自异→肝胆楚越；自同→万物皆一：两种视角，两种结论，是《齐物论》核心思想的体现。"},{id:"ermu_suoyi",term:"耳目之所宜",pinyin:"ěr mù zhī suǒ yí",meaning:"耳目（感官）所适宜（关注）的（差异）。所宜：所适合、所关注的；耳目之所宜：感官所执着的差异与好恶。"},{id:"you_xin_hu",term:"游心乎",pinyin:"yóu xīn hū",meaning:"让心神自由游走于……。游心：心神自由游走；乎：于，介词。"},{id:"de_zhihe",term:"德之和",pinyin:"dé zhī hé",meaning:"德性的和谐（境界）。德：德性、道德本性；和：和谐、融合。游心乎德之和：让心神游走于德性和谐的境界中——超越感官差异，回归德性本源。"},{id:"yi_tongyi",term:"一",pinyin:"yī",meaning:"同一、统一（的本质）。物视其所一：从万物同一的角度来看待（它们）。"},{id:"sang_shishi",term:"丧",pinyin:"sàng",meaning:"丧失、失去（的部分）。不见其所丧：看不见（万物）所丧失的（部分）。"},{id:"sang_qi_zu",term:"丧其足",pinyin:"sàng qí zú",meaning:"失去了（自己的）脚。丧：失去；足：脚。指王骀被砍去一足。"},{id:"you_ruotong",term:"犹",pinyin:"yóu",meaning:"如同、好像。副词，表比喻。视丧其足犹遗土也：看待失去脚这件事，就好像丢掉一块泥土一样。"},{id:"yi_tu",term:"遗土",pinyin:"yí tǔ",meaning:"丢掉的一块泥土。遗：丢失、遗落；土：泥土。视丧其足犹遗土也：把失去脚看作丢了一块泥土——形容王骀对形体残缺毫不在意，德充而形忘。"},{id:"bi_wei_ji",term:"彼为己",pinyin:"bǐ wèi jǐ",meaning:"他（王骀）修养自身。为己：为了自身、修养自己；非「自私」，而是向内修养。"},{id:"chang_xin",term:"常心",pinyin:"cháng xīn",meaning:"恒常不变的心（本心）。常：恒常、不变；心：内心。以其心得其常心：用（修养后的）心得到那恒常不变的本心。"},{id:"wu_zuizhi",term:"物何为最之哉",pinyin:"wù hé wèi zuì zhī zāi",meaning:"万物（外物）为什么还会聚集（归附）于他呢？何为：为什么；最：聚集、归聚，读 zuì；之：代词，指王骀；哉：疑问语气词。【古今异义】最：聚集，非「最高」。"},{id:"jian_jingzi",term:"鉴",pinyin:"jiàn",meaning:"照镜子、以……为镜。动词。人莫鉴于流水：人不用流水来照镜子。"},{id:"liu_shui",term:"流水",pinyin:"liú shuǐ",meaning:"流动的水。流水不能照出清晰的影像，喻动荡不定的心无法使人明察。"},{id:"zhi_shui",term:"止水",pinyin:"zhǐ shuǐ",meaning:"静止的水。止水能照出清晰的影像，喻静定的心能使人明察自身。"},{id:"zhi_neng_zhi",term:"唯止能止众止",pinyin:"wéi zhǐ néng zhǐ zhòng zhǐ",meaning:"只有静止（的水）才能使众多（来照镜的）人静止（安定）。唯止：只有静止；能止：能够使……静止；众止：众人的静止安定。三个「止」字：第一「止」为静止之水，第二「止」为动词使动，第三「止」为众人的安定。"},{id:"shou_ming_di",term:"受命于地",pinyin:"shòu mìng yú dì",meaning:"从大地（自然）那里承受天命（本性）。受命：承受天命、本性；于地：从大地。"},{id:"du_ye_zheng",term:"独也正",pinyin:"dú yě zhèng",meaning:"唯独（它）是端正的（不改变本性）。独：唯独；也：助词，表强调；正：端正、不偏。受命于地，唯松柏独也正：承受地命的树木中，唯有松柏独自端正（冬夏常青）。"},{id:"bao_shi_zheng",term:"保始之徵",pinyin:"bǎo shǐ zhī zhēng",meaning:"保守本初（本性）的征验（表现）。保始：保守最初的本性；徵：征验、表现，读 zhēng。"},{id:"jiang_qiu_ming",term:"将求名",pinyin:"jiāng qiú míng",meaning:"（只是）追求名声（的人）。将：只是、不过；求名：追求名声。"},{id:"zi_yao_zhe",term:"自要者",pinyin:"zì yāo zhě",meaning:"能够自我约束（克制）的人。自要：自我约束、自我要求；读 yāo。"},{id:"er_you_rushi",term:"而犹若是",pinyin:"ér yóu ruò shì",meaning:"尚且能够如此（勇猛）。犹：尚且；若是：像这样。将求名而能自要者而犹若是：只是追求名声却能自我约束的人尚且如此勇猛。"},{id:"guan_tiandi",term:"官天地",pinyin:"guān tiān dì",meaning:"以天地为官府（主宰天地）。官：主管、统辖；天地：天地万物。"},{id:"fu_wanwu",term:"府万物",pinyin:"fǔ wàn wù",meaning:"以万物为府库（包容万物）。府：府库、收藏之所；万物：一切事物。官天地·府万物：以天地为官署，以万物为府库——形容德充者胸怀宇宙的境界。"},{id:"bi_ta2",term:"彼",pinyin:"bǐ",meaning:"他（王骀）。指示代词，指德充之人。"},{id:"qie_jiangyao",term:"且",pinyin:"qiě",meaning:"将要、即将。副词，表将来。彼且择日而登假：他将要选择日子升登（羽化）。"},{id:"ze_ri_dengjia",term:"择日而登假",pinyin:"zé rì ér dēng jiǎ",meaning:"选择日子升登（羽化超脱）。择日：选择时日；登假：升登、羽化，通「登遐」；假：通「遐」，远去、升华。【通假字】假通「遐」，读 jiǎ。"},{id:"ken_yiwu_weishi",term:"彼且何肯以物为事乎",pinyin:"bǐ qiě hé kěn yǐ wù wéi shì hū",meaning:"他又怎么肯把外物当作（值得操心的）事呢！何肯：怎么肯、哪里肯；以物为事：把外物当作事务来操心。"}],h=[{id:"shentu_s1",label:"申徒嘉兀者也……不亦过乎",sentences:[[{text:"申徒嘉",glossary:"shentu_jia"},"，",{text:"兀者",glossary:"shentu_wuzhe"},"也，而与",{text:"郑子产",glossary:"zheng_zichan"},"同师于",{text:"伯昏无人",glossary:"bohun_wuren"},"。"],["子产谓申徒嘉曰：「我先",{text:"出",glossary:"chu_likai"},"则子",{text:"止",glossary:"zhi_liuzhu"},"，子先出则我止。」"],["其明日，又与合堂同席而坐。子产谓申徒嘉曰：「我先出则子止，子先出则我止。今我将出，子可以止乎？其未邪？"],["且子见",{text:"执政",glossary:"zhizheng_guanyuan"},"而",{text:"不违",glossary:"bu_wei_birang"},"，子",{text:"齐",glossary:"qi_dengtong"},"执政乎？」"],[{text:"申徒嘉",glossary:"shentu_jia"},"曰：「先生之门固有",{text:"执政",glossary:"zhizheng_guanyuan"},"焉如此哉？子",{text:"而",glossary:"er_jingran"},"说子之执政",{text:"而后人者也",glossary:"er_houren"},"。"],["闻之曰：『",{text:"鉴明",glossary:"jian_ming"},"则",{text:"尘垢不止",glossary:"chenggou_buzhi"},"，",{text:"止则不明也",glossary:"zhi_bu_ming"},"。",{text:"久与贤人处",glossary:"jiu_yu_xianren_chu"},"则",{text:"无过",glossary:"wu_guo2"},"。』"],["今子之",{text:"所取大者",glossary:"suo_qu_da"},"，先生也，而犹出言若是，不亦",{text:"过",glossary:"guo_cuowu"},"乎！」"]]},{id:"shentu_s2",label:"子产曰子既若是矣……不足以自反邪",sentences:[["子产曰：「子",{text:"既若是矣",glossary:"ji_ruoshi"},"，犹与尧争善。",{text:"计",glossary:"ji_guji"},"子之",{text:"德",glossary:"de_dezheng"},"，",{text:"不足以自反邪",glossary:"bu_zu_zifan"},"？」"]]},{id:"shentu_s3",label:"申徒嘉曰自状其过……唯有德者能之",sentences:[["申徒嘉曰：「",{text:"自状其过",glossary:"zi_zhuang_guo"},{text:"以不当亡者",glossary:"yi_bu_dang_wang"},"众；",{text:"不状其过",glossary:"bu_zhuang_guo"},{text:"以不当存者",glossary:"yi_bu_dang_cun"},"寡。"],[{text:"知不可奈何",glossary:"zhi_bunaihe"},"而",{text:"安之若命",glossary:"an_zhi_ruoming"},"，",{text:"唯有德者能之",glossary:"you_de_nengzhi"},"。"]]},{id:"shentu_s4",label:"游于羿之彀中……废然而反",sentences:[[{text:"游于羿之彀中",glossary:"you_yi_gouzhong"},"。",{text:"中央者",glossary:"zhong_yang_zhe"},"，",{text:"中地也",glossary:"zhong_di_ye"},"；然而",{text:"不中者",glossary:"bu_zhong_zhe"},"，",{text:"命也",glossary:"ming_tianming"},"。"],["人以其全足",{text:"笑吾不全足者",glossary:"xiao_bu_quanzu"},"众矣，我",{text:"怫然",glossary:"fu_ran"},"而怒，而适先生之所，则",{text:"废然而反",glossary:"fei_ran_fan"},"。"]]},{id:"shentu_s5",label:"不知先生之洗我以善邪……不亦过乎",sentences:[["不知先生之",{text:"洗我以善邪",glossary:"xi_yi_shan"},"？吾之",{text:"自寐邪",glossary:"zi_mei"},"？"],["吾与夫子",{text:"游",glossary:"you_xiangchu"},"十九年，而未尝知吾",{text:"兀者",glossary:"shentu_wuzhe"},"也。"],["今子与我游于",{text:"形骸之内",glossary:"xinghai_zhinei"},"，而子",{text:"索",glossary:"suo_xunqiu"},"我于",{text:"形骸之外",glossary:"xinghai_zhiwai"},"，不亦过乎！」"],["子产",{text:"蹴然",glossary:"cu_ran"},"改容更貌曰：「子",{text:"无乃称",glossary:"wu_nai_cheng"},"！」"]]}],_=[{id:"shentu_jia",term:"申徒嘉",pinyin:"shēn tú jiā",meaning:"人名，庄子虚构的断足圣人。申徒：复姓；嘉：名。与郑子产同师，以德充形残著称。"},{id:"shentu_wuzhe",term:"兀者",pinyin:"wù zhě",meaning:"被砍去一足的人。兀：断足；者：的人。古代刖刑所致。"},{id:"zheng_zichan",term:"郑子产",pinyin:"zhèng zǐ chǎn",meaning:"郑国的执政大夫子产，名公孙侨。历史上以善治著称，此处庄子借其形象讽刺以形骸（地位）取人。"},{id:"bohun_wuren",term:"伯昏无人",pinyin:"bó hūn wú rén",meaning:"人名，庄子虚构的得道之师。伯昏：字；无人：名，意为「无我之人」。庄子多篇出现，象征超越自我的至道者。"},{id:"chu_likai",term:"出",pinyin:"chū",meaning:"出门、离开（学堂）。子产要求两人不同时出门，暗示不愿与断足者并行，以免有损执政者颜面。"},{id:"zhi_liuzhu",term:"止",pinyin:"zhǐ",meaning:"留下、等候。我先出则子止：我先出去你就留下等候。"},{id:"zhizheng_guanyuan",term:"执政",pinyin:"zhí zhèng",meaning:"执掌政务的大官、执政者。此指子产自己的身份——郑国执政大夫。"},{id:"bu_wei_birang",term:"不违",pinyin:"bù wéi",meaning:"不回避、不让路。子产责申徒嘉见到执政者不知回避退让。"},{id:"qi_dengtong",term:"齐",pinyin:"qí",meaning:"等同于、与……相等。子齐执政乎：你把自己等同于执政者了吗？讽刺申徒嘉不知尊卑。"},{id:"er_jingran",term:"而",pinyin:"ér",meaning:"竟然、却。连词，表转折，含惊讶语气。子而说子之执政：你竟然（还在）夸耀你的执政身份。"},{id:"er_houren",term:"而后人者也",pinyin:"ér hòu rén zhě yě",meaning:"却把别人置于（自己）之后（的人）。后人：以他人为后、轻视他人；者也：判断语气。子而说子之执政而后人者也：你竟是那种夸耀执政地位、把别人踩在脚下的人。"},{id:"jian_ming",term:"鉴明",pinyin:"jiàn míng",meaning:"镜子明亮（洁净）。鉴：镜子；明：明亮、洁净。"},{id:"chenggou_buzhi",term:"尘垢不止",pinyin:"chén gòu bù zhǐ",meaning:"尘垢就不会停留（附着）。尘垢：灰尘污垢；不止：不停留。鉴明则尘垢不止：镜子明亮则尘垢无法附着——喻德充之人，外物（过失）无从沾染。"},{id:"zhi_bu_ming",term:"止则不明也",pinyin:"zhǐ zé bù míng yě",meaning:"（尘垢）停留了镜子就不明亮了。止：停留；不明：不明亮、蒙蔽。喻心有执念则德不充。"},{id:"jiu_yu_xianren_chu",term:"久与贤人处",pinyin:"jiǔ yǔ xián rén chǔ",meaning:"长久与贤人相处。久：长久；处：相处、共处。"},{id:"wu_guo2",term:"无过",pinyin:"wú guò",meaning:"没有过失。久与贤人处则无过：长久与贤人相处便不会有过失——申徒嘉以此反讽子产：你师从先生却仍出此言，岂非有过？"},{id:"suo_qu_da",term:"所取大者",pinyin:"suǒ qǔ dà zhě",meaning:"所获益最大的（来源）。所取：所获取、所学习；大者：最大的。今子之所取大者，先生也：你获益最大的来源，正是先生。"},{id:"guo_cuowu",term:"过",pinyin:"guò",meaning:"过失、错误。不亦过乎：不也是有过失吗？"},{id:"ji_ruoshi",term:"既若是矣",pinyin:"jì ruò shì yǐ",meaning:"（你）已经是这样（残缺）了。既：已经；若是：像这样；矣：语气词。子既若是矣，犹与尧争善：你已经是这样（断足残缺）了，还要与尧争高下。子产以形骸残缺来贬低申徒嘉。"},{id:"ji_guji",term:"计",pinyin:"jì",meaning:"估量、考量。计子之德：估量你的德行。"},{id:"de_dezheng",term:"德",pinyin:"dé",meaning:"德行、道德修养。计子之德，不足以自反邪：估量你的德行，还不足以自我反省吗？"},{id:"bu_zu_zifan",term:"不足以自反邪",pinyin:"bù zú yǐ zì fǎn yé",meaning:"还不足以自我反省吗？自反：自我反省、反思自身；邪：疑问语气词。子产讽刺申徒嘉德行不足、不知自省。"},{id:"zi_zhuang_guo",term:"自状其过",pinyin:"zì zhuàng qí guò",meaning:"自己陈述（承认）自己的过失。状：陈述、描述；过：过失（此处指断足之刑）。"},{id:"yi_bu_dang_wang",term:"以不当亡者",pinyin:"yǐ bù dāng wáng zhě",meaning:"认为（自己）不应当受刑（亡足）的人。以：认为；不当：不应当；亡：失去、受刑；者：的人。自状其过以不当亡者众：自己承认过失却认为不该受刑的人很多——即认罪但不服判。"},{id:"bu_zhuang_guo",term:"不状其过",pinyin:"bù zhuàng qí guò",meaning:"不陈述（不承认）自己的过失。不状：不陈述、不承认。"},{id:"yi_bu_dang_cun",term:"以不当存者",pinyin:"yǐ bù dāng cún zhě",meaning:"认为（自己）不应当保全（存活）的人。不当存：不应当存活、不值得保全；者：的人。不状其过以不当存者寡：不承认过失却认为自己不该活着的人很少——即既不认罪又不自责者极少。两句对举：认罪不服判者多，既认罪又彻底自责者少——世人皆执着于形骸得失。"},{id:"zhi_bunaihe",term:"知不可奈何",pinyin:"zhī bù kě nài hé",meaning:"知道（有些事）是无可奈何的。知：明白、了解；不可奈何：无法改变、无可奈何。"},{id:"an_zhi_ruoming",term:"安之若命",pinyin:"ān zhī ruò mìng",meaning:"安然接受它，就像接受命运一样。安之：安然接受；若命：如同接受天命。知不可奈何而安之若命：知道无可奈何便坦然接受——这是德充者的处世态度。"},{id:"you_de_nengzhi",term:"唯有德者能之",pinyin:"wéi yǒu dé zhě néng zhī",meaning:"只有有德之人才能做到这一点。唯：只有；有德者：有德行的人；能之：能够做到。"},{id:"you_yi_gouzhong",term:"游于羿之彀中",pinyin:"yóu yú yì zhī gòu zhōng",meaning:"在后羿的射程范围之内游走。羿：后羿，传说中的神射手；彀中：弓箭的射程范围之内；彀：张满弓，读 gòu。喻人生活在命运（危险）的射程之内，随时可能被「射中」（遭祸）。"},{id:"zhong_yang_zhe",term:"中央者",pinyin:"zhōng yāng zhě",meaning:"（箭）射中（目标）的（情况）。中央：射中靶心；者：表情况。⚠️ 中读 zhòng（射中），非「中央」方位词。"},{id:"zhong_di_ye",term:"中地也",pinyin:"zhòng dì yě",meaning:"是（箭）该射中的地方（命中注定）。中地：射中之处，命中之地；也：判断语气词。"},{id:"bu_zhong_zhe",term:"不中者",pinyin:"bù zhòng zhě",meaning:"（箭）没有射中（的情况）。不中：未射中；者：表情况。"},{id:"ming_tianming",term:"命也",pinyin:"mìng yě",meaning:"是命运（天命）。也：判断语气词。然而不中者，命也：然而没有被射中，是命运（的安排）。中与不中皆命——申徒嘉以此说明断足是命，无需怨恨，也无需他人怜悯。"},{id:"xiao_bu_quanzu",term:"笑吾不全足者",pinyin:"xiào wú bù quán zú zhě",meaning:"嘲笑我脚不完整的人。笑：嘲笑；不全足：脚不完整（断足）；者：的人。人以其全足笑吾不全足者众矣：用自己脚完整来嘲笑我断足的人多了。"},{id:"fu_ran",term:"怫然",pinyin:"fú rán",meaning:"愤怒的样子。怫：愤怒、气愤；然：……的样子。我怫然而怒：我（起初）愤怒起来。"},{id:"fei_ran_fan",term:"废然而反",pinyin:"fèi rán ér fǎn",meaning:"（怒气）消散地回来（释然而归）。废然：消散、放下的样子；反：通「返」，返回。而适先生之所，则废然而反：但去到先生那里，怒气便消散地回来了——先生的德化使申徒嘉释然。【通假字】反通「返」，读 fǎn。"},{id:"xi_yi_shan",term:"洗我以善邪",pinyin:"xǐ wǒ yǐ shàn yé",meaning:"用善道来涤洗（感化）我呢？洗：涤洗、感化；以善：用善道；邪：疑问语气词。不知先生之洗我以善邪：不知道是先生用善道感化了我。"},{id:"zi_mei",term:"自寐邪",pinyin:"zì mèi yé",meaning:"还是我自己（在先生影响下）自然醒悟呢？自寐：自我觉悟、自然醒悟；寐：通「昧」，蒙昧；自寐：从蒙昧中自我觉醒。邪：疑问语气词。【通假字】寐通「昧」，读 mèi。"},{id:"you_xiangchu",term:"游",pinyin:"yóu",meaning:"交游、相处。吾与夫子游十九年：我与先生相处了十九年。"},{id:"xinghai_zhinei",term:"形骸之内",pinyin:"xíng hái zhī nèi",meaning:"形体（外表）之内，即精神、德性的层面。形骸：形体、躯壳；之内：内在。游于形骸之内：在形体内在（精神层面）交游——超越外形，以德相交。"},{id:"suo_xunqiu",term:"索",pinyin:"suǒ",meaning:"寻找、探求。子索我于形骸之外：你却在形体（外表）之外寻找我（用外形来评判我）。"},{id:"xinghai_zhiwai",term:"形骸之外",pinyin:"xíng hái zhī wài",meaning:"形体（外表）之外，即以外形、地位来评判人的层面。形骸之外：执着于外在形体。游于形骸之内·索我于形骸之外：我们在精神层面交游，你却用外形来评判我——点明全篇主旨：德充者超越形骸。"},{id:"cu_ran",term:"蹴然",pinyin:"cù rán",meaning:"惭愧不安、局促的样子。蹴：局促、惭愧；然：……的样子。子产蹴然改容更貌：子产惭愧地改变了脸色和神情。"},{id:"wu_nai_cheng",term:"无乃称",pinyin:"wú nǎi chēng",meaning:"不要再说了！无乃：不要、莫；称：说话、称道。子产惭愧认错，请申徒嘉不要再说下去。"}],o=[{id:"wuzhi_s1",label:"鲁有兀者叔山无趾……请讲以所闻",sentences:[["鲁有",{text:"兀者",glossary:"wuzhi_wuzhe"},{text:"叔山无趾",glossary:"shushanwuzhi"},"，",{text:"踵见",glossary:"zhong_jian"},"仲尼。"],["仲尼曰：「子",{text:"不谨",glossary:"bu_jin"},"，",{text:"前既犯患若是矣",glossary:"qian_ji_fanhuan"},"。虽今来，",{text:"何及矣",glossary:"he_ji_yi"},"！」"],["无趾曰：「吾",{text:"唯",glossary:"wei_zhishi"},"不知",{text:"务",glossary:"wu_zhengwu"},"而轻用吾身，吾",{text:"是以亡足",glossary:"shi_yi_wangzu"},"。"],["今吾来也，",{text:"犹",glossary:"you_shangyou"},"有",{text:"尊足者",glossary:"zun_zu_zhe"},"存，吾是以务全之也。"],["夫天无不",{text:"覆",glossary:"fu_fugai"},"，地无不",{text:"载",glossary:"zai_chengzai"},"，吾以夫子为天地，",{text:"安知",glossary:"an_zhi"},"夫子之犹若是也！」"],["孔子曰：「丘则",{text:"陋矣",glossary:"lou_yi"},"！夫子",{text:"胡不入乎",glossary:"hu_bu_ru"},"？请讲以所闻。」"]]},{id:"wuzhi_s2",label:"无趾出……而况全德之人乎",sentences:[["无趾",{text:"出",glossary:"chu_likai2"},"。孔子曰：「弟子",{text:"勉之",glossary:"mian_zhi"},"！"],["夫无趾，兀者也，犹",{text:"务学",glossary:"wu_xue"},{text:"以复补",glossary:"yi_fubu"},{text:"前行之恶",glossary:"qianxing_zhi_e"},"，而况",{text:"全德之人",glossary:"quande_zhiren"},"乎！」"]]},{id:"wuzhi_s3",label:"无趾语老聃曰……不知至人之以是为己桎梏邪",sentences:[["无趾语老聃曰：「孔丘之于",{text:"至人",glossary:"zhi_ren2"},"，",{text:"其未邪",glossary:"qi_wei_ye"},"？"],[{text:"彼",glossary:"bi_kongqiu"},{text:"何",glossary:"he_weishenme"},{text:"宾宾",glossary:"bin_bin"},{text:"以学子为",glossary:"yi_xuezi_wei"},"？"],["彼且以",{text:"蕲",glossary:"qi_qiuqu"},{text:"以諔诡幻怪之名闻",glossary:"chu_gui_huanguai"},"，不知",{text:"至人",glossary:"zhi_ren2"},"之",{text:"以是为己桎梏",glossary:"yi_shi_zhigu"},"邪？」"]]},{id:"wuzhi_s4",label:"老聃曰胡不直使彼……天刑之安可解",sentences:[["老聃曰：「胡不",{text:"直",glossary:"zhi_zhijie"},{text:"使",glossary:"shi_shi"},{text:"彼",glossary:"bi_kongqiu"},"以死生为",{text:"一条",glossary:"yi_tiao"},"，以",{text:"可不可",glossary:"ke_buke"},"为",{text:"一贯者",glossary:"yi_guan"},"，解其",{text:"桎梏",glossary:"zhi_gu"},"，其可乎？」"],["无趾曰：「",{text:"天刑之",glossary:"tian_xing_zhi"},"，",{text:"安可解",glossary:"an_ke_jie"},"！」"]]}],u=[{id:"wuzhi_wuzhe",term:"兀者",pinyin:"wù zhě",meaning:"被砍去脚趾（或足）的人。兀：残缺、断足；者：的人。古代刖刑所致。"},{id:"shushanwuzhi",term:"叔山无趾",pinyin:"shū shān wú zhǐ",meaning:"人名，庄子虚构的断趾圣人。叔山：氏；无趾：名，因断趾而得名。"},{id:"zhong_jian",term:"踵见",pinyin:"zhǒng jiàn",meaning:"用脚跟（残足）走路来拜见。踵：脚跟；见：拜见。踵见仲尼：以残足走来拜见孔子——强调其形残而志不残。"},{id:"bu_jin",term:"不谨",pinyin:"bù jǐn",meaning:"不谨慎、不小心（行事）。谨：谨慎；不谨：行为不检点，以致犯罪受刑。"},{id:"qian_ji_fanhuan",term:"前既犯患若是矣",pinyin:"qián jì fàn huàn ruò shì yǐ",meaning:"之前已经犯下祸患到这种地步了。前：之前；既：已经；犯患：遭遇祸患、犯罪受刑；若是：像这样；矣：语气词。"},{id:"he_ji_yi",term:"何及矣",pinyin:"hé jí yǐ",meaning:"（现在来）还有什么用呢？何及：有什么用、来得及什么；矣：语气词。孔子以为无趾已受刑，来求学为时已晚——此处反映孔子执着于形骸得失的局限。"},{id:"wei_zhishi",term:"唯",pinyin:"wéi",meaning:"只是、正是因为。副词，表原因限定。吾唯不知务而轻用吾身：我只是因为不知道（珍重）正事而轻率地使用自己的身体。"},{id:"wu_zhengwu",term:"务",pinyin:"wù",meaning:"正事、要务（此处指珍重生命、修养德性）。不知务：不知道什么是真正重要的事。"},{id:"shi_yi_wangzu",term:"是以亡足",pinyin:"shì yǐ wáng zú",meaning:"因此失去了脚。是以：因此；亡：失去；足：脚。吾是以亡足：我因此失去了脚（受了刖刑）。"},{id:"you_shangyou",term:"犹",pinyin:"yóu",meaning:"还、仍然。副词，表仍有余存。今吾来也，犹有尊足者存：我现在来，还有比脚更尊贵的东西存在。"},{id:"zun_zu_zhe",term:"尊足者",pinyin:"zūn zú zhě",meaning:"比脚更尊贵的东西。尊：尊贵、重要；足：脚；尊足者：比脚更重要的（指德性、精神）。犹有尊足者存：还有比脚更珍贵的东西（德性）存在——无趾以此说明求学的意义超越形骸。"},{id:"fu_fugai",term:"覆",pinyin:"fù",meaning:"覆盖、笼罩。天无不覆：天没有不覆盖的（无所不包）。"},{id:"zai_chengzai",term:"载",pinyin:"zài",meaning:"承载、承托。地无不载：地没有不承载的（无所不容）。天无不覆·地无不载：天地包容万物，无趾以此比喻夫子（孔子）应如天地般包容——讽刺孔子以形骸取人，未能如天地般无私。"},{id:"an_zhi",term:"安知",pinyin:"ān zhī",meaning:"怎么知道、哪里料到。安：怎么、哪里；知：知道。安知夫子之犹若是也：哪里料到夫子竟然还是这样（以形骸取人）！"},{id:"lou_yi",term:"陋矣",pinyin:"lòu yǐ",meaning:"（我）浅陋了！陋：浅陋、见识短浅；矣：感叹语气词。丘则陋矣：孔子自我检讨，承认自己见识浅陋。"},{id:"hu_bu_ru",term:"胡不入乎",pinyin:"hú bù rù hū",meaning:"为何不进来呢？胡：为何、为什么；不入：不进来；乎：疑问语气词。孔子认错后邀请无趾入内讲学。"},{id:"chu_likai2",term:"出",pinyin:"chū",meaning:"出去、离开。无趾出：无趾离开之后（孔子对弟子说话）。"},{id:"mian_zhi",term:"勉之",pinyin:"miǎn zhī",meaning:"努力吧、勤勉啊。勉：努力、勤勉；之：语气助词。弟子勉之：弟子们要努力啊！"},{id:"wu_xue",term:"务学",pinyin:"wù xué",meaning:"致力于学习。务：致力于、专注于；学：学习求道。"},{id:"yi_fubu",term:"以复补",pinyin:"yǐ fù bǔ",meaning:"来弥补、来补救。以：用来；复补：重新补救、弥补。"},{id:"qianxing_zhi_e",term:"前行之恶",pinyin:"qián xíng zhī è",meaning:"以前行为的过失。前行：以前的行为；恶：过失、罪过。务学以复补前行之恶：致力于学习来弥补以前行为的过失。"},{id:"quande_zhiren",term:"全德之人",pinyin:"quán dé zhī rén",meaning:"德行完整（没有过失）的人。全德：德行完全、无缺；之人：的人。而况全德之人乎：何况德行完整的人呢！——孔子以无趾激励弟子：形残者尚且如此勤学，何况形全德全之人。"},{id:"zhi_ren2",term:"至人",pinyin:"zhì rén",meaning:"达到最高境界的人、得道之人。至：极致、最高；人：人。庄子理想人格之一。"},{id:"qi_wei_ye",term:"其未邪",pinyin:"qí wèi yé",meaning:"他（孔子）还差得远呢？其：他（孔子）；未：尚未、差得远；邪：疑问兼感叹语气词。孔丘之于至人，其未邪：孔丘距离至人，还差得远呢！"},{id:"bi_kongqiu",term:"彼",pinyin:"bǐ",meaning:"他（孔子）。指示代词，指孔丘。"},{id:"he_weishenme",term:"何",pinyin:"hé",meaning:"为什么、何必。疑问副词。彼何宾宾以学子为：他为什么还汲汲于以收徒讲学为事？"},{id:"bin_bin",term:"宾宾",pinyin:"bīn bīn",meaning:"汲汲然、勤勤恳恳（执着忙碌）的样子。宾宾：急切忙碌、孜孜不倦的样子。彼何宾宾以学子为：他为何还这样汲汲忙碌地以收徒讲学为事？"},{id:"yi_xuezi_wei",term:"以学子为",pinyin:"yǐ xué zǐ wéi",meaning:"以收徒讲学为（事业）。以……为：以……作为；学子：学生、门徒；为：作为（事务）。"},{id:"qi_qiuqu",term:"蕲",pinyin:"qí",meaning:"求取、希望得到。彼且以蕲……：他还想着求取……。【古今异义】蕲：求取，非地名「蕲春」，读 qí。"},{id:"chu_gui_huanguai",term:"諔诡幻怪之名闻",pinyin:"chù guǐ huàn guài zhī míng wén",meaning:"奇异诡谲、变幻怪异的名声。諔诡：奇异诡谲；幻怪：变幻怪异；名闻：名声、声名；读 chù guǐ。彼且以蕲以諔诡幻怪之名闻：他还想着靠奇异诡谲的言论来博取名声。"},{id:"yi_shi_zhigu",term:"以是为己桎梏",pinyin:"yǐ shì wéi jǐ zhì gù",meaning:"把这些（名声、学问）当作自己的枷锁。以是：把这些；为：当作；己：自己；桎梏：枷锁、束缚。不知至人之以是为己桎梏邪：不知道至人把这些（名声学问）视为自己的枷锁吗？"},{id:"zhi_gu",term:"桎梏",pinyin:"zhì gù",meaning:"枷锁、束缚。桎：脚镣；梏：手铐；合称枷锁。喻名声、学问等对精神的束缚。"},{id:"zhi_zhijie",term:"直",pinyin:"zhí",meaning:"径直、直接。副词。胡不直使彼：为何不直接让他（孔子）……。"},{id:"shi_shi",term:"使",pinyin:"shǐ",meaning:"使得、让。使动用法。胡不直使彼以死生为一条：为何不直接让他把死生看作同一回事。"},{id:"yi_tiao",term:"一条",pinyin:"yī tiáo",meaning:"同一条（脉络）、同一回事。一：同一；条：条理、脉络。以死生为一条：把死与生看作同一回事——超越生死对立。"},{id:"ke_buke",term:"可不可",pinyin:"kě bù kě",meaning:"可以与不可以（是非对错）。可：可以、对；不可：不可以、错。以可不可为一贯：把是与非看作同一贯通——超越是非对立。"},{id:"yi_guan",term:"一贯者",pinyin:"yī guàn zhě",meaning:"同一贯通的（道理）。一贯：一以贯之、融为一体；者：的东西。以死生为一条·以可不可为一贯：两句并举，是庄子「齐物」思想的核心——消解生死、是非的对立。"},{id:"tian_xing_zhi",term:"天刑之",pinyin:"tiān xíng zhī",meaning:"是天（命）对他的刑罚（束缚）。天：天命、自然；刑：刑罚、惩罚；之：代词，指孔子。天刑之：天命就是这样惩罚（束缚）他的——孔子执着于名声学问，是天命使然，非人力可解。"},{id:"an_ke_jie",term:"安可解",pinyin:"ān kě jiě",meaning:"怎么能解开（解救）呢？安：怎么、哪里；可：能够；解：解开、解救。天刑之，安可解：天命的刑罚，怎么能解开！——全篇点睛之语，意味深长。"}],m=[{id:"aitaita_s1",label:"鲁哀公问于仲尼……是必有异乎人者也",sentences:[[{text:"鲁哀公",glossary:"lu_aigong"},"问于仲尼曰：「卫有恶人焉，曰",{text:"哀骀它",glossary:"ai_tai_ta"},"。"],["丈夫与之处者，",{text:"思而不能去也",glossary:"si_buneng_qu"},"；妇人见之，请于父母曰：『与为人妻，宁为夫子妾』者，数十而未止也。"],["未尝有",{text:"闻其唱者也",glossary:"wen_qi_chang"},"，常",{text:"和人而已矣",glossary:"he_ren_eryi"},"。"],["无君人之",{text:"位",glossary:"wei_diwei"},"以",{text:"济",glossary:"ji_jiuji"},"乎人之死，无",{text:"聚禄",glossary:"ju_lu"},"以",{text:"望",glossary:"wang_weiyu"},"人之腹，"],["又以",{text:"恶骇天下",glossary:"e_hai_tianxia"},"，",{text:"和而不唱",glossary:"he_er_buchang"},"，知不出乎",{text:"四域",glossary:"si_yu"},"，且而",{text:"雌雄合乎前",glossary:"ci_xiong_he"},"，是必有异乎人者也。"]]},{id:"aitaita_s2",label:"寡人召而观之……是何人者也",sentences:[["寡人",{text:"召",glossary:"zhao_zhaojian"},"而观之，果以恶骇天下。"],["与寡人处，",{text:"不至以月数",glossary:"bu_zhi_yueshuo"},"，而寡人有意乎其为人也；",{text:"不至乎期年",glossary:"bu_zhi_qinian"},"，而寡人信之。"],["国无",{text:"宰",glossary:"zai_zaixiang"},"，而寡人",{text:"传国焉",glossary:"chuan_guo_yan"},"。"],[{text:"闷然",glossary:"men_ran"},"而",{text:"后应",glossary:"hou_ying"},"，",{text:"氾而若辞",glossary:"fan_er_ruoci"},"。"],["寡人",{text:"丑乎",glossary:"chou_hu"},"，",{text:"卒授之国",glossary:"zu_shou_guo"},"。"],[{text:"无几何也",glossary:"wu_jihe"},"，去寡人而行。寡人",{text:"恤焉",glossary:"xu_yan"},"，",{text:"若有亡也",glossary:"ruo_you_wang"},"，",{text:"若无与乐是国也",glossary:"ruo_wu_yu_le"},"。",{text:"是何人者也",glossary:"shi_he_ren"},"！」"]]},{id:"aitaita_s3",label:"仲尼曰丘也尝使于楚矣……爱使其形者也",sentences:[["仲尼曰：「丘也尝使于楚矣，适见",{text:"豚子食于其死母者",glossary:"tunzi_shiyu_simou"},"。"],[{text:"少焉眴若",glossary:"shao_yan_shun"},"，皆",{text:"弃之而走",glossary:"qi_zhi_erzou"},"。",{text:"不见己焉尔",glossary:"bu_jian_ji"},"，",{text:"不得其类焉尔",glossary:"bu_de_qilei"},"。"],[{text:"所爱其母者，非爱其形也，爱使其形者也",glossary:"ai_shiqi_xingzhe"},"。"]]},{id:"aitaita_s4",label:"战而死者……是必才全而德不形者也",sentences:[["战而死者，其人之葬也",{text:"不以翣资",glossary:"bu_yi_sha_zi"},"；",{text:"刖者之屡",glossary:"yue_zhe_zhi_jv"},"，",{text:"无为爱之",glossary:"wu_wei_aizhi"},"。",{text:"皆无其本矣",glossary:"jie_wu_qiben"},"。"],["为天子之",{text:"诸御",glossary:"zhu_yu"},"：",{text:"不爪翦",glossary:"bu_zhao_jian"},"，",{text:"不穿耳",glossary:"bu_chuan_er"},"；",{text:"取妻者止于外",glossary:"qu_qi_zhiwai"},"，",{text:"不得复使",glossary:"bu_de_fushi"},"。"],[{text:"形全犹足以为尔",glossary:"xingquan_zu_weier"},"，而况",{text:"全德之人",glossary:"quande_zhiren"},"乎！"],["今哀骀它",{text:"未言而信",glossary:"wei_yan_erxin"},"，",{text:"无功而亲",glossary:"wu_gong_erqin"},"，使",{text:"人授己国",glossary:"ren_shou_jiguo"},"，",{text:"唯恐其不受也",glossary:"weikong_bu_shou"},"，是必",{text:"才全而德不形",glossary:"cai_quan_debuxing"},"者也。」"]]},{id:"aitaita_s5",label:"哀公曰何谓才全……是之谓才全",sentences:[["哀公曰：「",{text:"何谓才全",glossary:"he_wei_caiquan"},"？」仲尼曰：「死生、存亡、穷达、贫富、贤与不肖、毁誉、饥渴、寒暑，是",{text:"事之变、命之行也",glossary:"shi_bian_ming_xing"},"。"],[{text:"日夜相代乎前",glossary:"ri_yue_xiangdai"},"，而知不能",{text:"规乎其始者也",glossary:"gui_hu_qishi"},"。故不足以",{text:"滑和",glossary:"gu_hua_he"},"，不可入于",{text:"灵府",glossary:"ling_fu"},"。"],[{text:"使之和豫",glossary:"shi_zhi_heyu"},"，",{text:"通而不失于兑",glossary:"tong_bu_shiyu_yue"},"。使日夜无",{text:"隙",glossary:"xi_jian"},"，而",{text:"与物为春",glossary:"yu_wu_weichun"},"，是",{text:"接而生时于心者也",glossary:"jie_er_shengshi"},"。是之谓",{text:"才全",glossary:"wei_caiquan"},"。」"]]},{id:"aitaita_s6",label:"何谓德不形……物不能离也",sentences:[["「",{text:"何谓德不形",glossary:"he_wei_debuxing"},"？」曰：「",{text:"平者，水停之盛也",glossary:"shui_ting_zhisheng"},"。其",{text:"可以为法也",glossary:"ke_yi_weifa"},"，",{text:"内保之而外不荡也",glossary:"nei_bao_waibudang"},"。"],["德者，",{text:"成和之修也",glossary:"cheng_he_zhixiu"},"。",{text:"德不形者，物不能离也",glossary:"debuxing_wubuli"},"。」"]]},{id:"aitaita_s7",label:"哀公异日以告闵子……德友而已矣",sentences:[[{text:"哀公异日以告闵子",glossary:"yi_ri_gao_minzi"},"曰：「始也吾以",{text:"南面而君天下",glossary:"nan_mian_juntian"},"，",{text:"执民之纪",glossary:"zhi_min_zhiji"},"而忧其死，吾自以为",{text:"至通矣",glossary:"zhi_tong_yi"},"。"],["今吾闻",{text:"至人之言",glossary:"zhiren_zhiyan"},"，恐吾无",{text:"其实",glossary:"wu_qi_shi"},"，",{text:"轻用吾身而亡吾国",glossary:"qing_yong_wangguo"},"。吾与孔丘非君臣也，",{text:"德友而已矣",glossary:"de_you_eryi"},"！」"]]}],l=[{id:"lu_aigong",term:"鲁哀公",pinyin:"lǔ āi gōng",meaning:"鲁国国君，谥号「哀」。历史人物，孔子晚年在鲁，哀公曾问政于孔子。此处庄子借其形象展开「才全德不形」的论述。"},{id:"ai_tai_ta",term:"哀骀它",pinyin:"āi tái tā",meaning:"人名，庄子虚构的奇丑得道者。哀骀：丑陋之貌；它：名。以极丑之形却德充感人，是「才全而德不形」的典型。"},{id:"si_buneng_qu",term:"思而不能去也",pinyin:"sī ér bù néng qù yě",meaning:"（与他相处后）思念他而不能离去。思：思念、留恋；不能去：无法离开。"},{id:"wen_qi_chang",term:"闻其唱者也",pinyin:"wén qí chàng zhě yě",meaning:"听到他（主动）倡导（发起）什么的（人）。唱：通「倡」，倡导、首先发起；闻其唱：听说他主动倡导什么。【通假字】唱通「倡」，读 chàng。未尝有闻其唱者：从来没有听说他主动倡导什么。"},{id:"he_ren_eryi",term:"和人而已矣",pinyin:"hé rén ér yǐ yǐ",meaning:"只是随和地附和别人罢了。和：附和、顺应；而已矣：罢了。常和人而已矣：只是随时顺应别人而已——从不主动，却令人倾心。"},{id:"wei_diwei",term:"位",pinyin:"wèi",meaning:"（君主的）地位、权位。无君人之位：没有统治他人的地位（不是君主）。"},{id:"ji_jiuji",term:"济",pinyin:"jì",meaning:"救济、帮助。济乎人之死：救人于死亡（危难）之中。"},{id:"ju_lu",term:"聚禄",pinyin:"jù lù",meaning:"积聚的俸禄（财富）。聚：积聚；禄：俸禄、财富。无聚禄：没有积聚的财富。"},{id:"wang_weiyu",term:"望",pinyin:"wàng",meaning:"填满、满足（口腹之欲）。望人之腹：填满别人的肚子（以财富养活他人）。【古今异义】望：满足、充实，非「盼望」。"},{id:"e_hai_tianxia",term:"恶骇天下",pinyin:"è hài tiān xià",meaning:"以丑陋的外貌震骇天下。恶：丑陋；骇：震惊、惊骇；天下：天下人。又以恶骇天下：而且以丑陋的外貌令天下人震惊。"},{id:"he_er_buchang",term:"和而不唱",pinyin:"hé ér bù chàng",meaning:"只是附和而不主动倡导。和：附和、顺应；不唱：不主动发起、不倡导。呼应「常和人而已矣」，是哀骀它处世方式的核心特征。"},{id:"si_yu",term:"四域",pinyin:"sì yù",meaning:"四境之内、方圆之地。四域：四方的疆域范围。知不出乎四域：智识不超出方圆之地（见识并不广博）。"},{id:"ci_xiong_he",term:"雌雄合乎前",pinyin:"cí xióng hé hū qián",meaning:"男女（雌雄）都聚集在他面前（归附于他）。雌雄：女性与男性；合：聚合、归聚；乎前：在他面前。且而雌雄合乎前：而且男男女女都聚集在他面前——无论男女皆被其德所吸引。"},{id:"zhao_zhaojian",term:"召",pinyin:"zhào",meaning:"召见、传召。寡人召而观之：我（哀公）召他来看看。"},{id:"bu_zhi_yueshuo",term:"不至以月数",pinyin:"bù zhì yǐ yuè shǔ",meaning:"不到几个月（相处时间）。不至：不到、不满；以月数：以月来计算。"},{id:"bu_zhi_qinian",term:"不至乎期年",pinyin:"bù zhì hū qī nián",meaning:"不到一整年。期年：满一年、整整一年；读 jī nián。不至乎期年，而寡人信之：不到一年，我就完全信任他了。"},{id:"zai_zaixiang",term:"宰",pinyin:"zǎi",meaning:"宰相、执政大臣。国无宰：国家没有宰相（空缺）。"},{id:"chuan_guo_yan",term:"传国焉",pinyin:"chuán guó yān",meaning:"把国家（政务）托付给他。传：托付、传授；国：国家（政务）；焉：代词，指哀骀它。"},{id:"men_ran",term:"闷然",pinyin:"mèn rán",meaning:"沉默不语、漠然的样子。闷：沉默、漠然；然：……的样子。闷然而后应：沉默了很久才回应。"},{id:"hou_ying",term:"后应",pinyin:"hòu yìng",meaning:"迟迟才回应。后：迟、之后；应：回应、答复。闷然而后应：沉默漠然，迟迟才回应——不急于表态，顺其自然。"},{id:"fan_er_ruoci",term:"氾而若辞",pinyin:"fàn ér ruò cí",meaning:"漫不经心地好像要推辞（的样子）。氾：漫然、随意，读 fàn；若辞：好像要推辞。闷然而后应，氾而若辞：沉默迟应，漫然若辞——哀骀它对权位毫不在意的神态。"},{id:"chou_hu",term:"丑乎",pinyin:"chǒu hū",meaning:"（寡人）感到惭愧啊。丑：惭愧、羞愧；乎：语气词，表感叹。寡人丑乎：我感到惭愧（因为他若辞，我反而觉得不好意思）。"},{id:"zu_shou_guo",term:"卒授之国",pinyin:"zú shòu zhī guó",meaning:"最终还是把国家（政务）授予他。卒：最终、终于；授：授予；之：代词，指哀骀它；国：国家政务。"},{id:"wu_jihe",term:"无几何也",pinyin:"wú jǐ hé yě",meaning:"没过多久。无几何：没有多少时间、不久；也：语气词。"},{id:"xu_yan",term:"恤焉",pinyin:"xù yān",meaning:"忧虑、惆怅（的样子）。恤：忧虑、悲伤；焉：语气词，兼表状态。寡人恤焉：我（哀公）感到忧伤惆怅。"},{id:"ruo_you_wang",term:"若有亡也",pinyin:"ruò yǒu wáng yě",meaning:"好像失去了什么（重要的东西）。若：好像；有亡：有所失去；也：语气词。"},{id:"ruo_wu_yu_le",term:"若无与乐是国也",pinyin:"ruò wú yǔ lè shì guó yě",meaning:"好像没有人可以共同享有这个国家（的快乐）了。若无与：好像没有人可以一起；乐：享乐、共享；是国：这个国家；也：语气词。"},{id:"shi_he_ren",term:"是何人者也",pinyin:"shì hé rén zhě yě",meaning:"这究竟是什么样的人啊！是：这；何人：什么样的人；者也：感叹判断语气。哀公以此收束对哀骀它的描述，充满困惑与叹服。"},{id:"tunzi_shiyu_simou",term:"豚子食于其死母者",pinyin:"tún zǐ shí yú qí sǐ mǔ zhě",meaning:"小猪在死去的母猪身上吃奶。豚子：小猪；食于其死母：在已死的母猪身上吃奶。喻依赖的不是母体之形，而是使其活着的生机。"},{id:"shao_yan_shun",term:"少焉眴若",pinyin:"shǎo yān shùn ruò",meaning:"不一会儿，（小猪）惊惶四顾的样子。少焉：片刻、不一会儿；眴若：惊惶四顾貌；眴：惊视，读 shùn。"},{id:"qi_zhi_erzou",term:"弃之而走",pinyin:"qì zhī ér zǒu",meaning:"离开（母猪）跑开了。弃：抛弃、离开；走：奔跑（古义）。皆弃之而走：小猪们全都离开死母猪跑开了。"},{id:"bu_jian_ji",term:"不见己焉尔",pinyin:"bù jiàn jǐ yān ěr",meaning:"（母猪）不再像同类一样看顾自己了。不见己：母亲不再把自己当同类（活着时）看顾；焉尔：语助词。一说指小猪已看不出母猪活着的样子。"},{id:"bu_de_qilei",term:"不得其类焉尔",pinyin:"bù dé qí lèi yān ěr",meaning:"（小猪）找不到自己的同类（了）。不得其类：不能从死母猪身上得到同类的气息与庇护。两句写小猪识出母亲已死而散去——形在而生机已失，则形不足依。"},{id:"ai_shiqi_xingzhe",term:"所爱其母者，非爱其形也，爱使其形者也",pinyin:"suǒ ài qí mǔ zhě fēi ài qí xíng yě ài shǐ qí xíng zhě yě",meaning:"（小猪）爱它母亲的，不是爱它的形体，而是爱那个使它形体活着的（生机）。使其形者：使形体运作的东西——精神、生机。庄子以此说明：人所爱的根本是内在生机（德），而非外在形体。"},{id:"bu_yi_sha_zi",term:"不以翣资",pinyin:"bù yǐ shà zī",meaning:"不用翣饰来（送葬）。翣：shà，棺材两旁的扇形饰物；资：供给、置办。战死的人无全尸，葬时不备翣饰——翣因棺而设，无棺则翣无所用，喻失去根本则附属之物皆无意义。"},{id:"yue_zhe_zhi_jv",term:"刖者之屡",pinyin:"yuè zhě zhī jù",meaning:"断足者（丢弃）的鞋。刖：断足之刑，读 yuè；屡：通「屦」，鞋，读 jù。断足者已无足，鞋自然没人爱惜——喻物因有「本」（足）才有价值。"},{id:"wu_wei_aizhi",term:"无为爱之",pinyin:"wú wéi ài zhī",meaning:"没有必要爱惜它。为：需要；爱：爱惜。刖者之屡，无为爱之：断足者的鞋子，没必要爱惜（因为它已失去被使用的根本）。"},{id:"jie_wu_qiben",term:"皆无其本矣",pinyin:"jiē wú qí běn yǐ",meaning:"（翣与屡）都失去了自己的根本。皆：都；本：根本、依托。翣之本在棺、屡之本在足；本失则物废——庄子以此铺垫：形骸只是「本」（德）的附属。"},{id:"zhu_yu",term:"诸御",pinyin:"zhū yù",meaning:"天子身边的侍御之人（嫔妃侍从）。诸：众；御：侍御、侍奉天子者。为天子之诸御：作为天子挑选的侍御者。"},{id:"bu_zhao_jian",term:"不爪翦",pinyin:"bù zhǎo jiǎn",meaning:"不剪指甲。爪：指甲；翦：通「剪」，修剪。选入宫的侍御者要保留完整之形（不修剪），以示形体完好。"},{id:"bu_chuan_er",term:"不穿耳",pinyin:"bù chuān ěr",meaning:"不穿耳洞（不戴耳饰）。古代女子穿耳为饰，天子诸御为保全形体完好而不穿耳。不爪翦·不穿耳：皆因「形全」而受特殊对待。"},{id:"qu_qi_zhiwai",term:"取妻者止于外",pinyin:"qǔ qī zhě zhǐ yú wài",meaning:"（宫中）娶了妻子的人要留在宫外。取：通「娶」；止于外：停居在宫外。【通假字】取通「娶」。"},{id:"bu_de_fushi",term:"不得复使",pinyin:"bù dé fù shǐ",meaning:"不能再（入宫）服役。复使：再次供职役使。取妻者止于外，不得复使：娶妻者被视为形已损（不再纯全），故不得再侍御。"},{id:"xingquan_zu_weier",term:"形全犹足以为尔",pinyin:"xíng quán yóu zú yǐ wéi ěr",meaning:"形体完整尚且足以如此（被看重）。形全：形体完好；犹：尚且；为尔：如此。连侍御都要保全形貌——可见形全受人重视；何况德全呢！"},{id:"quande_zhiren",term:"全德之人",pinyin:"quán dé zhī rén",meaning:"德性完备的人。全：完备、无缺；德：德性。而况全德之人乎：何况德性完备的人（更应被敬重）——形全尚且可贵，德全更胜于形全。"},{id:"wei_yan_erxin",term:"未言而信",pinyin:"wèi yán ér xìn",meaning:"不曾说话就受人信任。未言：未开口；信：被信服。今哀骀它未言而信：哀骀它不说话就能使人信服。"},{id:"wu_gong_erqin",term:"无功而亲",pinyin:"wú gōng ér qīn",meaning:"没有功劳就被人亲近。亲：被亲近、爱戴。未言而信·无功而亲：无言行之功而众人自附——正是「德充」之验，非靠言语功业。"},{id:"ren_shou_jiguo",term:"人授己国",pinyin:"rén shòu jǐ guó",meaning:"别人把国家托付给他。授：托付、交付；己国：自己的国家。使人授己国：使人愿意把国家交给他治理。"},{id:"weikong_bu_shou",term:"唯恐其不受也",pinyin:"wéi kǒng qí bù shòu yě",meaning:"只怕他不肯接受。唯恐：只怕；受：接受。哀公授国，唯恐哀骀它不肯接受——德充者不慕权位而权位自归。"},{id:"cai_quan_debuxing",term:"才全而德不形",pinyin:"cái quán ér dé bù xíng",meaning:"才性完备而德性不外显。才全：内在才性（精神）不受外物消耗而完满；德不形：德充盈于内而不表露于外。是必才全而德不形者也：这必定是才全而德不形的人——全篇核心概念，下文哀公问其详。"},{id:"he_wei_caiquan",term:"何谓才全",pinyin:"hé wèi cái quán",meaning:"什么是「才全」？何谓：什么是；才全：才性完备。"},{id:"shi_bian_ming_xing",term:"事之变、命之行也",pinyin:"shì zhī biàn mìng zhī xíng yě",meaning:"是人事的变迁、天命的运行。事之变：事物变化的种种形态；命之行：天命的流行运转。死生存亡穷达贫富等八事，皆属事变与命行，非人力所能左右。"},{id:"ri_yue_xiangdai",term:"日夜相代乎前",pinyin:"rì yè xiāng dài hū qián",meaning:"日夜交替（更迭）在眼前。相代：互相替代、交替；乎前：在眼前。指变化不断在眼前发生，从未停歇。"},{id:"gui_hu_qishi",term:"规乎其始者也",pinyin:"guī hū qí shǐ zhě yě",meaning:"测度（窥见）它们的开端。规：测度、窥见；始：开端、起点。而知不能规乎其始者也：而（人的）智识不能窥见变化的开端——变化无穷，智不能穷其源。"},{id:"gu_hua_he",term:"滑和",pinyin:"gǔ hé",meaning:"扰乱内心的和谐。滑：扰乱、搅动，读 gǔ；和：内心的和谐状态。故不足以滑和：所以（这些变化）不足以扰乱内心的和谐。⚠️ 滑读 gǔ，非「滑溜」。"},{id:"ling_fu",term:"灵府",pinyin:"líng fǔ",meaning:"心灵（精神的）居所、内心最深处。灵：心灵；府：府库、居所。不可入于灵府：（变化）不能侵入心灵深处——内心安定，外变不入。"},{id:"shi_zhi_heyu",term:"使之和豫",pinyin:"shǐ zhī hé yù",meaning:"使内心和顺安逸。使：使得；之：指心；和豫：和顺安逸、从容自得。使之和豫：让心灵保持和顺安逸。"},{id:"tong_bu_shiyu_yue",term:"通而不失于兑",pinyin:"tōng ér bù shī yú yuè",meaning:"通达而不失于愉悦。通：通达（与万物感通）；兑：通「悦」，愉悦，读 yuè。内通外顺，喜悦不失——心通万物而不失自身的和悦。【通假字】兑通「悦」。"},{id:"xi_jian",term:"隙",pinyin:"xì",meaning:"间隙、间断。使日夜无隙：使（心与天地的往来）日夜没有间断。一作「使日夜无郤」。"},{id:"yu_wu_weichun",term:"与物为春",pinyin:"yǔ wù wéi chūn",meaning:"与万物一起如春天般和煦（生机勃发）。为春：呈春天和煦之象。与物为春：对万物保持春阳般的温和生意。"},{id:"jie_er_shengshi",term:"接而生时于心者也",pinyin:"jiē ér shēng shí yú xīn zhě yě",meaning:"（这种与物相接的状态）在心中生出时宜（的感应）的。接：与万物相接；生时：生出适时的生机、感应；于心：在心中。是接而生时于心者也：这就是与物相接而心中随时生发适宜感应（的境界）。"},{id:"wei_caiquan",term:"才全",pinyin:"cái quán",meaning:"才性完备。是之谓才全：这就叫做「才全」——顺事变、安命行，变化不入心，心常和豫如春，是才全之定义。"},{id:"he_wei_debuxing",term:"何谓德不形",pinyin:"hé wèi dé bù xíng",meaning:"什么是「德不形」？德不形：德性充盈而不外露成形。"},{id:"shui_ting_zhisheng",term:"平者，水停之盛也",pinyin:"píng zhě shuǐ tíng zhī shèng yě",meaning:"平静，是水完全静止的极致状态。平：平静；水停之盛：水静止到极致的充盈状态。以止水喻德不形：内极静而自能鉴物。"},{id:"ke_yi_weifa",term:"可以为法也",pinyin:"kě yǐ wéi fǎ yě",meaning:"可以作为（效法的）准则。法：法则、标准。止水可作镜鉴，德充之静可为众人法则。"},{id:"nei_bao_waibudang",term:"内保之而外不荡也",pinyin:"nèi bǎo zhī ér wài bù dàng yě",meaning:"内心保持（宁静）而外表不摇荡。内保之：内心持守那平静；外不荡：外在不摇荡、不动摇。内静外定，如水不荡——德不形的状态。"},{id:"cheng_he_zhixiu",term:"德者，成和之修也",pinyin:"dé zhě chéng hé zhī xiū yě",meaning:"德，是成就（内心）和谐的修养。成和：成就和顺（内心的和谐）；修：修养、功夫。德的内核是成就和谐而非外在表现。"},{id:"debuxing_wubuli",term:"德不形者，物不能离也",pinyin:"dé bù xíng zhě wù bù néng lí yě",meaning:"德不外露的人，万物（众人）不能离开他。物不能离：众人自然归附、不愿离去。德不形如水停，静而能鉴、含而不露，故万物自附不离——全篇「德充符」的点题。"},{id:"yi_ri_gao_minzi",term:"哀公异日以告闵子",pinyin:"āi gōng yì rì yǐ gào mǐn zǐ",meaning:"后来哀公把（这事）告诉闵子。异日：他日、日后；以告：以此告诉；闵子：闵子骞，孔子弟子。"},{id:"nan_mian_juntian",term:"南面而君天下",pinyin:"nán miàn ér jūn tiān xià",meaning:"面向南方君临天下。南面：古代君主坐北朝南，面南为君；君天下：君临天下、治理天下。始也吾以南面而君天下：起初我面南而坐统治天下。"},{id:"zhi_min_zhiji",term:"执民之纪",pinyin:"zhí mín zhī jì",meaning:"执掌治理百姓的纲纪。执：执掌；民之纪：治理民众的法度纲纪。执民之纪而忧其死：把持治民纲纪、为百姓的生死担忧。"},{id:"zhi_tong_yi",term:"至通矣",pinyin:"zhì tōng yǐ",meaning:"（自认为）非常通达了。至：极、非常；通：通达（明理）；矣：语气词。吾自以为至通矣：我曾自认为非常通达了。"},{id:"zhiren_zhiyan",term:"至人之言",pinyin:"zhì rén zhī yán",meaning:"得道之人（孔子）的话。至人：达到最高境界的人，此处指孔子（哀公口中之「至人」）。"},{id:"wu_qi_shi",term:"无其实",pinyin:"wú qí shí",meaning:"没有那实际的（德行）。实：实德、真实的修养。恐吾无其实：恐怕我没有与通达之名相应的实德。"},{id:"qing_yong_wangguo",term:"轻用吾身而亡吾国",pinyin:"qīng yòng wú shēn ér wáng wú guó",meaning:"轻率地使用自己的身体而使国家危亡。轻用：轻率耗用；亡：使……灭亡。喻自恃智识、忧劳过度，反伤身祸国。"},{id:"de_you_eryi",term:"德友而已矣",pinyin:"dé yǒu ér yǐ yǐ",meaning:"只是以德相交的朋友罢了。德友：以德行相交的朋友；而已矣：罢了。吾与孔丘非君臣也，德友而已矣：我与孔丘不是君臣，只是以德相交的朋友——哀公由「君临」悟到「德友」，呼应全篇以德为尊。"}],p=[{id:"yinqi_s1",label:"闉跂支离无脣说卫灵公……此谓诚忘",sentences:[[{text:"闉跂支离无脣",glossary:"yinqi_zhili_wuchun"},"说",{text:"卫灵公",glossary:"wei_linggong"},"，灵公说之，而视全人：",{text:"其脰肩肩",glossary:"qi_dou_jianjian"},"。"],[{text:"甕㼜大瘿",glossary:"weng_lei_dayingr"},"说",{text:"齐桓公",glossary:"qi_huangong"},"，桓公说之，而视全人：其脰肩肩。"],["故",{text:"德有所长",glossary:"de_you_suochang"},"而",{text:"形有所忘",glossary:"xing_you_suowang"},"。"],["人不忘其",{text:"所忘",glossary:"suo_wang_ying"},"而忘其",{text:"所不忘",glossary:"suo_bu_wang"},"，此谓",{text:"诚忘",glossary:"cheng_wang"},"。"]]},{id:"yinqi_s2",label:"故圣人有所游……又恶用人",sentences:[["故圣人有所游，而",{text:"知为孽",glossary:"zhi_wei_nie"},"，",{text:"约为胶",glossary:"yue_wei_jiao"},"，",{text:"德为接",glossary:"de_wei_jie"},"，",{text:"工为商",glossary:"gong_wei_shang"},"。"],[{text:"圣人不谋",glossary:"shengren_bu_mou"},"，",{text:"恶用知",glossary:"e_yong_zhi"},"？",{text:"不斵",glossary:"bu_zhuo"},"，恶用胶？",{text:"无丧",glossary:"wu_sang"},"，恶用德？",{text:"不货",glossary:"bu_huo"},"，恶用商？"],["四者，",{text:"天鬻也",glossary:"tian_yu"},"。",{text:"天鬻者，天食也",glossary:"tian_yu_shi"},"。",{text:"既受食于天",glossary:"shou_shi_yu_tian"},"，",{text:"又恶用人",glossary:"you_e_yong_ren"},"！"]]},{id:"yinqi_s3",label:"有人之形……独成其天",sentences:[["有人之形，无人之情。有人之形，故群于人；无人之情，故是非不得于身。"],[{text:"眇乎小哉",glossary:"miao_hu_xiao"},"，所以属于人也；",{text:"謷乎大哉",glossary:"ao_hu_da"},"，独成其天。"]]}],x=[{id:"yinqi_zhili_wuchun",term:"闉跂支离无脣",pinyin:"yīn qí zhī lí wú chún",meaning:"人名，庄子虚构的形体残缺者。闉跂：跛足、行走不便；支离：肢体散乱残缺；无脣：没有嘴唇。三种残缺集于一身，极言其形残，以衬托其德充。"},{id:"wei_linggong",term:"卫灵公",pinyin:"wèi líng gōng",meaning:"卫国国君，谥号「灵」。历史人物，在位期间以好色著称，此处庄子借其形象说明德充可令人忘形。"},{id:"qi_dou_jianjian",term:"其脰肩肩",pinyin:"qí dòu jiān jiān",meaning:"那些（形体完整的）人的脖子（看起来）细小单薄。脰：脖子，读 dòu；肩肩：细小、单薄的样子。而视全人，其脰肩肩：（灵公）再看那些形体完整的人，反觉得他们脖子细小单薄——喻德充者令人忘其形残，反觉全人形貌不足。"},{id:"weng_lei_dayingr",term:"甕㼜大瘿",pinyin:"wèng lěi dà yǐng",meaning:"人名，庄子虚构的另一形残得道者。甕㼜：大肚子、形体臃肿；大瘿：颈部长有巨大肿瘤；瘿：颈部肿瘤，读 yǐng。与闉跂支离无脣并列，皆以极丑之形衬托德充之美。"},{id:"qi_huangong",term:"齐桓公",pinyin:"qí huán gōng",meaning:"齐国国君，春秋五霸之首。历史人物，此处庄子借其形象与卫灵公对举，说明德充感人不分贤愚君主。"},{id:"de_you_suochang",term:"德有所长",pinyin:"dé yǒu suǒ cháng",meaning:"德行有所超长（超越常人）。德：德行；有所长：有所超越、有所长处。"},{id:"xing_you_suowang",term:"形有所忘",pinyin:"xíng yǒu suǒ wàng",meaning:"形体（的残缺）有所被遗忘。形：形体；有所忘：被人忘却。德有所长而形有所忘：德行超长则形体的残缺被人遗忘——是「德充符」全篇的核心命题。"},{id:"suo_wang_ying",term:"所忘",pinyin:"suǒ wàng",meaning:"本应忘记的（形体残缺）。所忘：应当忘记之事，指形骸的残缺。人不忘其所忘：人们不忘记本应忘记的（形体残缺）。"},{id:"suo_bu_wang",term:"所不忘",pinyin:"suǒ bù wàng",meaning:"本不应忘记的（德性）。所不忘：不应当忘记之事，指德性本源。而忘其所不忘：却忘记了本不应忘记的（德性）。"},{id:"cheng_wang",term:"诚忘",pinyin:"chéng wàng",meaning:"真正的遗忘（本末倒置的遗忘）。诚：真正、确实；忘：遗忘。人不忘所忘而忘所不忘，此谓诚忘：不忘形体却忘德性，这才叫真正的遗忘（本末倒置）。"},{id:"zhi_wei_nie",term:"知为孽",pinyin:"zhì wéi niè",meaning:"智谋（对圣人而言）是祸害。知：智慧、智谋；为：是、成为；孽：祸害、灾殃。圣人游于道，智谋反成累赘。"},{id:"yue_wei_jiao",term:"约为胶",pinyin:"yuē wéi jiāo",meaning:"约束（礼义）是束缚（胶水）。约：约束、礼义规范；胶：胶水，喻粘滞束缚。"},{id:"de_wei_jie",term:"德为接",pinyin:"dé wéi jiē",meaning:"德行（刻意施展）是（用来）交接（攀附）的手段。德：德行；接：交接、攀附他人。德本自然，若刻意施展则沦为交际手段。"},{id:"gong_wei_shang",term:"工为商",pinyin:"gōng wéi shāng",meaning:"技艺（用来牟利）是买卖（营利）。工：技艺、才能；商：买卖、营利。知为孽·约为胶·德为接·工为商：四句并举，说明圣人游于道，世俗的智谋、礼约、德行、技艺皆成负累。"},{id:"shengren_bu_mou",term:"圣人不谋",pinyin:"shèng rén bù móu",meaning:"圣人不谋划（不用智谋）。谋：谋划、算计。"},{id:"e_yong_zhi",term:"恶用知",pinyin:"wū yòng zhī",meaning:"哪里用得上智谋？恶：哪里、何必，读 wū；用：用得上；知：智谋。圣人不谋，恶用知：圣人不谋划，哪里用得上智谋？"},{id:"bu_zhuo",term:"不斵",pinyin:"bù zhuó",meaning:"不砍削（不加人工雕琢）。斵：砍削、雕琢，读 zhuó。不斵，恶用胶：不砍削（木头），哪里用得上胶水——喻不强行约束，则礼义之胶无用武之地。"},{id:"wu_sang",term:"无丧",pinyin:"wú sàng",meaning:"没有丧失（德性本自圆满）。无丧：无所丧失；无丧，恶用德：本无丧失，哪里用得上（刻意施展的）德行。"},{id:"bu_huo",term:"不货",pinyin:"bù huò",meaning:"不做买卖（不以技艺牟利）。货：货卖、买卖；不货，恶用商：不做买卖，哪里用得上商贾之道。"},{id:"tian_yu",term:"天鬻也",pinyin:"tiān yù yě",meaning:"是天（自然）的养育。天：自然、天道；鬻：养育、哺育，读 yù；也：判断语气词。四者（不谋·不斵·无丧·不货），天鬻也：这四者（圣人的处世方式）是天道自然的养育。"},{id:"tian_yu_shi",term:"天鬻者，天食也",pinyin:"tiān yù zhě tiān shí yě",meaning:"天道养育的，就是天道供养（的食粮）。天食：天道的供养、自然的滋养；也：判断语气词。"},{id:"shou_shi_yu_tian",term:"既受食于天",pinyin:"jì shòu shí yú tiān",meaning:"既然已经从天道那里获得了供养。既：既然、已经；受食：接受供养；于天：从天道。"},{id:"you_e_yong_ren",term:"又恶用人",pinyin:"yòu wū yòng rén",meaning:"又何必用（依赖）人为的（手段）呢！又：又、还；恶用：何必用；人：人为的手段。既受食于天，又恶用人：既已受天道供养，又何必依赖人为的智谋礼义——点明圣人顺天而行、无需人为造作的核心思想。"},{id:"miao_hu_xiao",term:"眇乎小哉",pinyin:"miǎo hū xiǎo zāi",meaning:"多么渺小啊！眇：微小、渺小，读 miǎo；乎：语气词，表感叹；小哉：多么小啊。眇乎小哉，所以属于人也：多么渺小啊，（有人之形）所以归属于人群之中。"},{id:"ao_hu_da",term:"謷乎大哉",pinyin:"áo hū dà zāi",meaning:"多么宏大啊！謷：高大、宏大，读 áo；乎：感叹语气词；大哉：多么大啊。謷乎大哉，独成其天：多么宏大啊，（无人之情）独自成就其天然本性。眇乎小·謷乎大：对举，形与天的对比——形体归属于人（小），德性独成其天（大）。"}],z=[{id:"wuqing_s1",label:"惠子谓庄子曰人故无情乎……恶得不谓之人",sentences:[["惠子谓庄子曰：「人故",{text:"无情乎",glossary:"wu_qing"},"？」庄子曰：「然。」"],["惠子曰：「人而无情，何以谓之人？」"],["庄子曰：「",{text:"道与之貌",glossary:"dao_yu_mao"},"，",{text:"天与之形",glossary:"tian_yu_xing"},"，",{text:"恶得",glossary:"e_de"},{text:"不谓之人",glossary:"bu_wei_zhiren"},"？」"]]},{id:"wuqing_s2",label:"惠子曰既谓之人……常因自然而不益生也",sentences:[["惠子曰：「既谓之人，恶得无情？」"],["庄子曰：「是非吾所谓",{text:"情也",glossary:"qing_suowei"},"。吾所谓",{text:"无情者",glossary:"wuqing_zhe"},"，言人之不以",{text:"好恶",glossary:"hao_wu"},{text:"内伤其身",glossary:"nei_shang_shen"},"，常",{text:"因自然",glossary:"yin_ziran"},"而不",{text:"益生也",glossary:"yi_sheng"},"。」"]]},{id:"wuqing_s3",label:"惠子曰不益生……子以坚白鸣",sentences:[["惠子曰：「不益生，何以有其身？」"],["庄子曰：「道与之貌，天与之形，无以好恶内伤其身。"],["今子",{text:"外乎子之神",glossary:"wai_hu_shen"},"，",{text:"劳乎子之精",glossary:"lao_hu_jing"},"，",{text:"倚树而吟",glossary:"yi_shu_yin"},"，",{text:"据槁梧而瞑",glossary:"ju_gaowu_ming"},"。"],[{text:"天选子之形",glossary:"tian_xuan_xing"},"，",{text:"子以坚白鸣",glossary:"jianbaiming"},"。」"]]}],b=[{id:"wu_qing",term:"无情乎",pinyin:"wú qíng hū",meaning:"没有情感吗？无情：没有情感；乎：疑问语气词。惠子以「情」为人之所必有，庄子则重新定义「情」的含义。"},{id:"dao_yu_mao",term:"道与之貌",pinyin:"dào yǔ zhī mào",meaning:"道赋予他（人）容貌。道：大道、自然之道；与：赋予、给予；之：代词，指人；貌：容貌、外貌。"},{id:"tian_yu_xing",term:"天与之形",pinyin:"tiān yǔ zhī xíng",meaning:"天赋予他（人）形体。天：自然、天道；与：赋予；形：形体、身体。道与之貌·天与之形：道天赋予人容貌与形体，人因此成其为人——庄子以此说明「人」的定义在于道天所赋，而非情感。"},{id:"e_de",term:"恶得",pinyin:"wū dé",meaning:"怎么能、哪里能。恶：怎么、哪里，读 wū；得：能够。恶得不谓之人：怎么能不称他为人呢？"},{id:"bu_wei_zhiren",term:"不谓之人",pinyin:"bù wèi zhī rén",meaning:"不称他为人。谓：称、叫做；之：代词，指他；人：人。恶得不谓之人：怎么能不称他为人？"},{id:"qing_suowei",term:"情也",pinyin:"qíng yě",meaning:"（我所说的）情感。是非吾所谓情也：这不是我所说的「情」。庄子区分两种「情」：惠子之情=喜怒好恶；庄子之情=顺应自然、不以好恶伤身。"},{id:"wuqing_zhe",term:"无情者",pinyin:"wú qíng zhě",meaning:"（我所说的）无情的意思。吾所谓无情者：我所说的「无情」，是指……——庄子重新定义「无情」，非无喜怒，而是不以好恶内伤其身。"},{id:"hao_wu",term:"好恶",pinyin:"hào wù",meaning:"喜好与厌恶。好：喜好，读 hào；恶：厌恶，读 wù。不以好恶内伤其身：不因喜好与厌恶而在内心伤害自身。"},{id:"nei_shang_shen",term:"内伤其身",pinyin:"nèi shāng qí shēn",meaning:"在内心（精神上）伤害自身。内：向内、在内心；伤：伤害；其身：自身。不以好恶内伤其身：不让好恶之情在内心损伤自己——是庄子「无情」的核心定义。"},{id:"yin_ziran",term:"因自然",pinyin:"yīn zì rán",meaning:"顺应自然（的本性）。因：顺应、依循；自然：自然而然的状态。常因自然：常常顺应自然——不强加人为的好恶于自然本性之上。"},{id:"yi_sheng",term:"益生也",pinyin:"yì shēng yě",meaning:"增益生命（人为地添加于生命之上）。益：增益、添加；生：生命；也：语气词。不益生：不人为地增益生命——顺其自然，不强求延寿或享乐。常因自然而不益生：常顺应自然而不人为添益生命，是庄子「无情」的完整表述。"},{id:"wai_hu_shen",term:"外乎子之神",pinyin:"wài hū zǐ zhī shén",meaning:"使你的精神外驰（耗散于外）。外：使……向外耗散，动词；乎：于；子之神：你的精神。今子外乎子之神：你现在使自己的精神向外耗散。"},{id:"lao_hu_jing",term:"劳乎子之精",pinyin:"láo hū zǐ zhī jīng",meaning:"使你的精气劳损（耗费）。劳：使……劳损、耗费；精：精气、精力。外乎子之神·劳乎子之精：精神外驰、精气劳损——庄子批评惠子以辩论耗散精神，正是「以好恶内伤其身」的表现。"},{id:"yi_shu_yin",term:"倚树而吟",pinyin:"yǐ shù ér yín",meaning:"靠着树（疲倦地）吟咏（沉吟）。倚：倚靠；树：树木；吟：吟咏、沉吟叹息。"},{id:"ju_gaowu_ming",term:"据槁梧而瞑",pinyin:"jù gǎo wú ér míng",meaning:"趴在枯梧桐上打盹（昏昏欲睡）。据：趴着、凭靠；槁梧：枯干的梧桐木（几案）；瞑：闭目、打盹，读 míng。倚树而吟·据槁梧而瞑：两句描绘惠子辩论后精疲力竭的状态，是「劳乎子之精」的具体表现。"},{id:"tian_xuan_xing",term:"天选子之形",pinyin:"tiān xuǎn zǐ zhī xíng",meaning:"天（自然）选定了你的形体（赋予你这副身体）。天选：天道选定、自然赋予；子之形：你的形体。"},{id:"jianbaiming",term:"子以坚白鸣",pinyin:"zǐ yǐ jiān bái míng",meaning:"你却用「坚白论」来自鸣得意（炫耀）。坚白：「坚白石」之辩，惠子（名家）的著名论题，以「坚」与「白」可以分离为论；鸣：鸣叫、自鸣得意，喻炫耀才能。天选子之形，子以坚白鸣：天赋予你形体（自然之德），你却用坚白辩论来耗损精神——庄子以此讽刺惠子舍本逐末，以人为的名辩伤害天赋的自然本性。"}];return(v,i)=>{const w=r("DaoReadingPrelude"),a=r("DaoTextReading"),s=r("DaoKeywordCards"),g=r("DaoLineGuide");return q(),j("div",null,[i[0]||(i[0]=n("h1",{id:"庄子·德充符",tabindex:"-1"},[e("庄子·德充符 "),n("a",{class:"header-anchor",href:"#庄子·德充符","aria-label":'Permalink to "庄子·德充符"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[e("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),i[2]||(i[2]=n("blockquote",null,[n("p",null,[n("strong",null,"「德充符」三字，是全篇的纲领。")]),n("p",null,"「德」不是外在的道德标签，而是内在生命的安定与充盈；「充」是充实于内；「符」则是自然显露的征验。德真正充足时，不必倚赖容貌、地位、功业或言辞来证明自己，人会自然感到它的力量。"),n("p",null,"《人间世》追问人在险恶世道如何不受伤，《德充符》接着追问：什么样的生命，才不容易被外物所伤？庄子让断足者、丑陋者和形体奇异者逐一出现，不是把残缺神秘化，而是借最尖锐的反差，拆开我们对「完整」的习惯判断。")],-1)),t(w,{title:"从形残而德全，进入庄子的德充符",summary:"《德充符》集中写一批外形不全、容貌丑陋或不合常规的人。庄子借王骀、申徒嘉、叔山无趾、哀骀它等人物反问：人的完整究竟在形貌、地位与评价中，还是在不被外物摇动的内在德性中？",points:[{label:"先看",text:"顺着六个段落，看庄子怎样不断颠倒形残、貌丑与完整的常识。"},{label:"再问",text:"才全、德不形与无情，如何共同说明生命的内在充盈？"},{label:"最后",text:"当我们评价自己和他人时，是否仍停在形骸、履历与标签之外？"}],hint:"这一篇不要把人物的形体奇异当作奇闻。每一段真正要处理的，都是人如何被外在标准遮住了内在生命。"}),i[3]||(i[3]=n("h2",{id:"一、王骀·不言之教",tabindex:"-1"},[e("一、王骀·不言之教 "),n("a",{class:"header-anchor",href:"#一、王骀·不言之教","aria-label":'Permalink to "一、王骀·不言之教"'},"​")],-1)),i[4]||(i[4]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:y,glossary:d,"default-mode":"classic","aria-label":"德充符·王骀 原文"}),i[5]||(i[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"兀者",pinyin:["wù","zhě"],meaning:"被砍去一足的人。古代刖刑（砍足之刑）的受刑者。兀：截断、残缺。"},{term:"王骀",pinyin:["wáng","tái"],meaning:"人名，虚构人物。王：超越；骀：劣马，引申为平庸。名字有「以平庸超越一切」之意。"},{term:"中分鲁",pinyin:["zhōng","fēn","lǔ"],meaning:"把鲁国的学人平分了——各占一半。中分：对半分。"},{term:"不言之教",pinyin:["bù","yán","zhī","jiào"],meaning:"不用言语的教化。与老子「行不言之教」相通。"},{term:"无形而心成",pinyin:["wú","xíng","ér","xīn","chéng"],meaning:"没有具体形式，却让人内心有所成就。"},{term:"奚假鲁国",pinyin:["xī","jiǎ","lǔ","guó"],meaning:"何止是鲁国。奚假：何止、哪里只是。"},{term:"肝胆楚越",pinyin:["gān","dǎn","chǔ","yuè"],meaning:"从差异的角度看，肝和胆的距离就像楚国和越国一样遥远。"},{term:"万物皆一",pinyin:["wàn","wù","jiē","yī"],meaning:"从相同的角度看，万物都是一体的。"},{term:"游心",pinyin:["yóu","xīn"],meaning:"让心自由游走于德性的和谐之中。全篇核心词，与逍遥游的「游」同一境界在人间的落地。"},{term:"官天地",pinyin:["guān","tiān","dì"],meaning:"以天地为官署（胸怀天地）。官：管理、统辖。"},{term:"府万物",pinyin:["fǔ","wàn","wù"],meaning:"以万物为府库（包容万物）。府：储藏、包容。"},{term:"直寓六骸",pinyin:["zhí","yù","liù","hái"],meaning:"只是暂时寄居在六骸（身体）之中。直：只是；寓：寄居；六骸：头、躯干、四肢。"}]}),i[6]||(i[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(g,{title:"虚而往，实而归——不言之教",subtitle:"王骀从不主动讲课，但跟随他的人，空着心去，满载而归。",lines:[{text:"虚而往，实而归。",tone:"感召",guide:"这是常季对王骀最精准的描述，也是全段的第一个谜：王骀从不主动讲课，从不主动议论，但跟随他的人，空着心去，满载而归。这是什么样的教？庄子借孔子之口，用整段来回答这个问题。"},{text:"死生亦大矣，而不得与之变；虽天地覆坠，亦将不与之遗。",tone:"守宗",guide:"这是孔子对王骀内心状态的第一层描述：死生，是天下最大的事——但王骀的心不因死生而改变；天地翻覆，是宇宙最大的灾难——但王骀不会随之消亡。不是王骀不知道死生的重大，而是他的心有一个更深的根基，不被任何外物撼动。这个根基，庄子叫它「宗」——守其宗。"},{text:"审乎无假而不与物迁，命物之化而守其宗也。",tone:"核心",guide:"这是全段最重要的一句，也是王骀内心状态的核心：审乎无假（洞察到自己不需要依赖任何外物）、不与物迁（内心不随外物的变化而迁移）、命物之化（顺应万物的变化，不是抗拒，而是顺应）、守其宗（同时守住自己的根本）。顺应变化，同时守住根本——这不是矛盾，而是德充符的核心张力。随波逐流是「与物迁」；固执不变是「假于物」；王骀做的是第三件事：在流动中守住那个不动的中心。"},{text:"自其异者视之，肝胆楚越也；自其同者视之，万物皆一也。",tone:"两种视角",guide:"这是庄子哲学中最著名的「两种视角」：从差异的角度看，肝和胆紧挨着，但从功能、形态、位置细分，它们的差异就像楚国和越国一样遥远——万物各不相同，差异无穷无尽；从相同的角度看，楚国和越国虽然相距遥远，但都是天地间的存在，都归于同一个道——万物皆一，无有分别。王骀选择了第二种视角——「自其同者视之」。所以他看自己失去的脚，就像丢掉一块泥土：不是麻木，不是压抑，而是真正看见了那个更大的「一」，让「失去」这件事，自然地缩小到了它本来的尺寸。"},{text:"游心乎德之和。",tone:"游心",guide:"这是《德充符》全篇的核心词，也是庄子给出的最终答案：让心自由游走于德性的和谐之中。不是「努力保持平静」，不是「压制悲伤」，而是心真正找到了那个和谐的居所，自然地游走其中，不被外物牵引。这个「游」字，与逍遥游的「游」是同一个字——德充符的「游心」，是逍遥游在人间的落地形式。"},{text:"人莫鉴于流水而鉴于止水。唯止能止众止。",tone:"止水",guide:"这是全段最美的一个比喻：人照镜子，不用流动的水，而用静止的水——因为只有静止的水面，才能映照出清晰的影像。「唯止能止众止」：只有内心真正静止的人，才能让周围人的心也静止下来。王骀的感召力，不来自他的言语，不来自他的才能，来自他内心那片静止的水面。这也解释了「虚而往，实而归」的秘密：跟随王骀的人，被他的静止所感染，自己内心的躁动慢慢平息，于是在静止中，看见了原本被躁动遮蔽的东西——这就是「实而归」。"}]}),i[7]||(i[7]=n("h2",{id:"二、申徒嘉·子产·游于形骸之内",tabindex:"-1"},[e("二、申徒嘉·子产·游于形骸之内 "),n("a",{class:"header-anchor",href:"#二、申徒嘉·子产·游于形骸之内","aria-label":'Permalink to "二、申徒嘉·子产·游于形骸之内"'},"​")],-1)),i[8]||(i[8]=n("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:h,glossary:_,"default-mode":"classic","aria-label":"德充符·申徒嘉 原文"}),i[9]||(i[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"申徒嘉",pinyin:["shēn","tú","jiā"],meaning:"人名，虚构人物。申徒：复姓。兀者，被砍去一足之人。"},{term:"郑子产",pinyin:["zhèng","zǐ","chǎn"],meaning:"郑国著名政治家，春秋时期贤相。此处代表世俗权贵。"},{term:"伯昏无人",pinyin:["bó","hūn","wú","rén"],meaning:"师名，虚构人物。伯昏：极昏暗（不以聪明自居）；无人：无我。"},{term:"合堂同席",pinyin:["hé","táng","tóng","xí"],meaning:"在同一厅堂、同一席位坐着。"},{term:"执政",pinyin:["zhí","zhèng"],meaning:"执掌政权的人，此处指子产本人（郑国执政大夫）。"},{term:"彀中",pinyin:["gòu","zhōng"],meaning:"弓箭射程之内。游于羿之彀中：人生活在命运的射程之内，随时可能被命运之箭射中。"},{term:"怫然而怒",pinyin:["fú","rán","ér","nù"],meaning:"勃然大怒。怫然：愤怒的样子。"},{term:"废然而反",pinyin:["fèi","rán","ér","fǎn"],meaning:"愤怒消散了，回归平静。废然：消散、平息；反：返回（平静）。"},{term:"形骸",pinyin:["xíng","hái"],meaning:"形体。游于形骸之内：在精神层面相处；索我于形骸之外：用外在形貌评判人。"},{term:"蹴然",pinyin:["cù","rán"],meaning:"惭愧、局促不安的样子。子产被申徒嘉点醒后，蹴然改容。"}]}),i[10]||(i[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(g,{title:"游于形骸之内，是真正的看见",subtitle:"德性充盈的人，一句话就能让对方看见自己的浅薄。",lines:[{text:"我先出则子止，子先出则我止。",tone:"身份",guide:"故事从这句话开始，看似平常，实则是全段最深的讽刺：子产是郑国执政大夫，位高权重；申徒嘉是断足之人，在世俗眼中地位低下。两人同拜一位老师，子产却嫌弃与残疾人同行有失身份。庄子用这个细节，把问题直接摆出来：在老师门下，身份还重要吗？形体还重要吗？"},{text:"鉴明则尘垢不止，止则不明也。久与贤人处则无过。",tone:"明镜",guide:"申徒嘉引用的这句话，是对子产最精准的反击：镜子越明亮，灰尘越不会停留——内心越清明，杂念（执着于身份、形体的念头）越不会停留。子产在老师门下学了这么久，内心却还有「执政大夫」这块灰尘——这才是真正的「不明」。申徒嘉没有直接攻击子产，而是说：你来这里最大的收获是先生，但你在先生门下，还说出这样的话——你辜负了先生。"},{text:"知不可奈何而安之若命，唯有德者能之。",tone:"安命",guide:"这是《德充符》第二段的核心句，也是与《人间世》最直接的呼应：《人间世》叶公子高段说「知其不可奈何而安之若命，德之至也」；这里申徒嘉说「知不可奈何而安之若命，唯有德者能之」。两篇互文，共同指向同一个境界：不是认命，不是软弱，而是在洞察了「无可奈何」之后，仍然选择安然接受——这需要极大的德性力量。"},{text:"游于羿之彀中。中央者，中地也；然而不中者，命也。",tone:"命运",guide:"这是全篇最震撼的一个比喻：人活着，就是在后羿的弓箭射程里行走。随时可能被射中——被疾病、被刑罚、被灾难射中。被射中的，是命；没有被射中的，也是命。申徒嘉被射中了（受了刖刑，失去了脚）；子产没有被射中（保全了双脚，还当了执政大夫）——但这不是因为子产比申徒嘉更有德行。这只是命。子产用「全足」来嘲笑「不全足」——这是在用命运的偶然，来建立道德的优越感。申徒嘉用这个比喻，把这种优越感彻底瓦解了。"},{text:"吾与夫子游十九年，而未尝知吾兀者也。",tone:"十九年",guide:"这是全段最动人的一句话。申徒嘉跟随伯昏无人学习十九年——老师从来没有把他当作残疾人看待。不是老师没有眼睛，看不见他断了的脚；而是老师的眼睛，看的不是形体，看的是形体之内的那个人。十九年，老师一直在「游于形骸之内」与他相处。"},{text:"今子与我游于形骸之内，而子索我于形骸之外，不亦过乎！",tone:"点睛",guide:"这是全段的点睛之笔，也是《德充符》全篇的核心命题第一次完整表达：游于形骸之内——在精神、德性的层面上与人相处，看见那个人本身；索我于形骸之外——用外在形体、身份、地位来评判人，只看见那个人的壳。子产犯的错，不是傲慢，而是「索我于形骸之外」——他在老师门下学了这么久，眼睛还停在形骸之外。申徒嘉没有愤怒，没有控诉，只是平静地说出这一句——然后子产惭愧地改变了神色。这就是德充符的力量：不需要争论，不需要愤怒，德性充盈的人，一句话就能让对方看见自己的浅薄。"}]}),i[11]||(i[11]=n("h2",{id:"三、叔山无趾·天刑之-安可解",tabindex:"-1"},[e("三、叔山无趾·天刑之，安可解 "),n("a",{class:"header-anchor",href:"#三、叔山无趾·天刑之-安可解","aria-label":'Permalink to "三、叔山无趾·天刑之，安可解"'},"​")],-1)),i[12]||(i[12]=n("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:o,glossary:u,"default-mode":"classic","aria-label":"德充符·叔山无趾 原文"}),i[13]||(i[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"叔山无趾",pinyin:["shū","shān","wú","zhǐ"],meaning:"人名，虚构人物。无趾：没有脚趾，即兀者（受过刖刑）。"},{term:"踵见仲尼",pinyin:["zhǒng","jiàn","zhòng","ní"],meaning:"用脚跟走路去拜见孔子。踵：脚跟。因为没有脚趾，只能用脚跟走路。"},{term:"尊足",pinyin:["zūn","zú"],meaning:"比脚更尊贵的东西（指德性、精神）。犹有尊足者存：还有比脚更值得珍视的东西。"},{term:"丘则陋矣",pinyin:["qiū","zé","lòu","yǐ"],meaning:"我孔丘真是浅陋啊！陋：浅陋、见识短浅。孔子的自我批评。"},{term:"弟子勉之",pinyin:["dì","zǐ","miǎn","zhī"],meaning:"弟子们要努力啊！"},{term:"諔诡",pinyin:["chù","guǐ"],meaning:"奇异怪诞。蕲以諔诡幻怪之名闻：希望以奇异怪诞的名声闻名于世。"},{term:"幻怪",pinyin:["huàn","guài"],meaning:"幻变怪诞。与「諔诡」连用，形容不寻常的名声。"},{term:"桎梏",pinyin:["zhì","gù"],meaning:"脚镣手铐，比喻束缚。至人把这些（名声、学问）当作自己的枷锁。"}]}),i[14]||(i[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(g,{title:"天刑之，安可解",subtitle:"每个人都有自己的「天刑」——那些天性中无法超越的局限，是命，不是错。",lines:[{text:"子不谨，前既犯患若是矣。虽今来，何及矣！",tone:"评判",guide:"这是全篇最让人意外的一幕：孔子，那个在第一段被描述为「将以王骀为师」的孔子，见到叔山无趾，第一句话就是拒绝。「你之前犯了错，现在来，还来得及吗？」庄子用这个细节，揭示了孔子的局限：他知道道理，但他的第一反应，仍然是「形骸之外」的评判——看见的是断足（受过刑罚的人），而不是那个人本身。"},{text:"犹有尊足者存，吾是以务全之也。",tone:"尊足",guide:"无趾的这句回答，是全段最深刻的一句话：我失去了脚——但还有比脚更尊贵的东西存在，我来这里，是为了保全那个更尊贵的东西。什么是比脚更尊贵的东西？德性。精神。生命的本质力量。脚只是形骸，失去了不可惜；德性才是生命的核心，值得用尽全力去保全。"},{text:"吾以夫子为天地，安知夫子之犹若是也！",tone:"失望",guide:"这句话，是无趾对孔子最深的失望，也是最深的期待：我把你当作天地——天无不覆，地无不载——以为你会像天地一样，包容一切，不遗弃任何人。哪里知道，你也会用「受过刑罚」来拒绝一个人。这句话让孔子立刻惭愧：「丘则陋矣！」庄子在这里，不是要否定孔子，而是要说：即使是孔子，在「形骸之外」的执着上，也还没有完全超越。这才是「天刑之」的伏笔。"},{text:"天刑之，安可解！",tone:"天刑",guide:"这是全段，也是前三段中，最冷峻的一句话。老聃问：能不能让孔子把死生看作一条，把可否看作一贯，从而解开他的枷锁？无趾说：天刑之，安可解。这是上天对孔子施加的刑罚——不是惩罚，而是天性使然的局限：孔子天生就是那种执着于礼义、执着于名声、执着于「有为」的人，这是他的天性，不是人力可以改变的。这句话极为深刻，也极为悲悯：庄子不是在嘲笑孔子，而是在说：每个人都有自己的「天刑」——那些天性中无法超越的局限，是命，不是错。但也正因为是「天刑」，所以无解——孔子永远无法成为至人，正如至人永远不需要成为孔子。"}]}),i[15]||(i[15]=n("h2",{id:"四、哀骀它·才全而德不形",tabindex:"-1"},[e("四、哀骀它·才全而德不形 "),n("a",{class:"header-anchor",href:"#四、哀骀它·才全而德不形","aria-label":'Permalink to "四、哀骀它·才全而德不形"'},"​")],-1)),i[16]||(i[16]=n("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:m,glossary:l,"default-mode":"classic","aria-label":"德充符·哀骀它 原文"}),i[17]||(i[17]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"鲁哀公",pinyin:["lǔ","āi","gōng"],meaning:"鲁国国君，孔子晚年时期的君主。"},{term:"哀骀它",pinyin:["āi","tái","tā"],meaning:"人名，虚构人物。哀：丑陋；骀：劣马（平庸）；它：他者。名字即暗示其貌丑而德充。"},{term:"恶人",pinyin:["è","rén"],meaning:"相貌丑陋之人。恶：丑陋（此处非道德意义上的「坏」）。"},{term:"以恶骇天下",pinyin:["yǐ","è","hài","tiān","xià"],meaning:"以丑陋的外貌震惊天下。骇：震惊、惊吓。"},{term:"传国焉",pinyin:["chuán","guó","yān"],meaning:"把国家托付给他。"},{term:"才全",pinyin:["cái","quán"],meaning:"才性完整——内在本性完整，不被外物消耗。全篇核心概念之一。"},{term:"德不形",pinyin:["dé","bù","xíng"],meaning:"德性不外露，不刻意表现。全篇核心概念之一。德不形者，物不能离也。"},{term:"滑和",pinyin:["gǔ","hé"],meaning:"扰乱内心的和谐。不足以滑和：命运的变化不足以扰乱内心的和谐。"},{term:"与物为春",pinyin:["yǔ","wù","wéi","chūn"],meaning:"与万物同处于春天般的生机之中。才全状态的最美描述。"},{term:"水停之盛",pinyin:["shuǐ","tíng","zhī","shèng"],meaning:"水静止时最充盈的状态。德不形的意象：德充盈到极致，不需要外在形式。"},{term:"德友",pinyin:["dé","yǒu"],meaning:"以德性相交的朋友，超越君臣关系的精神之交。"}]}),i[18]||(i[18]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(g,{title:"才全而德不形——不唱，只和；不求，只在",subtitle:"德性充盈到极致，连「德」的形态都消失了，只剩下那个让万物自然归附的力量。",lines:[{text:"未尝有闻其唱者也，常和人而已矣。",tone:"不唱",guide:"这是哀骀它最核心的特征，也是全段的第一个谜：他从不主动倡导什么，只是随和地应和别人——没有主张，没有号召，没有表演。但男人思念他，女人愿意为他做妾，国君要把国家托付给他。为什么？庄子用整段来回答：因为他是「才全而德不形」的人。"},{text:"所爱其母者，非爱其形也，爱使其形者也。",tone:"使其形者",guide:"这是全段最精妙的一个比喻：小猪爱母猪，不是爱那副形体——母猪死了，形体还在，小猪却跑开了。小猪爱的，是那个「使形体运动」的东西——生命力，精神，那个让形体成为「母亲」的东西。孔子用这个比喻，说明了一个根本道理：人与人之间真正的吸引，从来不是形体，而是那个「使其形者」——生命的本质力量。哀骀它极丑，但人们归附他——因为他身上那个「使其形者」，无比充盈。这就是「德充符」——德性充盈，自然符验于外。"},{text:"才全而德不形者也。",tone:"核心",guide:"这是《德充符》全篇最核心的概念，在这里第一次完整说出：才全——才性完整，不是才能出众，而是内在本性完整，不被外物消耗；德不形——德性不外露，不是没有德，而是德性充盈到不需要刻意表现。「才全」是内在的状态，「德不形」是外在的表现。才性越完整，越不需要用外在的形式来证明自己。哀骀它「未言而信，无功而亲」——这正是「德不形」的极致。"},{text:"死生、存亡、穷达、贫富、贤与不肖、毁誉、饥渴、寒暑，是事之变、命之行也。故不足以滑和，不可入于灵府。",tone:"才全",guide:"这是孔子对「才全」的定义，也是《德充符》最重要的一段论述：庄子列出八对命运的变化——死生、存亡、穷达、贫富……这些是人间世里最让人执着、最让人恐惧的东西。孔子说：这些都是「事之变、命之行」——事物变化的规律，命运运行的轨迹。它们日夜在眼前交替，但智慧无法追溯它们的起始。既然无法掌控，就「不足以滑和」——不足以扰乱内心的和谐；「不可入于灵府」——不能进入心灵最深处的府库。「才全」的人，不是没有遭遇这些变化，而是这些变化无法扰动他内心深处的那片和谐。"},{text:"使日夜无隙，而与物为春。",tone:"与物为春",guide:"这是「才全」状态的最美描述：让内心日夜没有间隙——不是「有时平静，有时动荡」，而是始终保持完整，没有被外物撕开的缝隙。「与物为春」——与万物同处于春天般的生机之中。不是强迫自己积极，而是内心的和谐自然地向外散发，让周围的一切都感受到那种温暖与生机。这就是哀骀它让人「思而不能去」的秘密——他的内心是春天，靠近他的人，都感受到了那个春天。"},{text:"平者，水停之盛也。其可以为法也，内保之而外不荡也。",tone:"水停",guide:"这是对「德不形」的定义，也是全篇最美的一个意象：平静，是水静止时最充盈的状态。注意：不是「水少了才平静」，而是「水停之盛」——水充盈到极致，反而最平静。德性也是如此：不是德少了才不显现，而是德充盈到极致，反而不需要外在的形式来表现——内保之而外不荡，内心保持它，外表不被扰动。这就是「德不形」——不是没有德，而是德充盈到了「水停之盛」的状态。"},{text:"吾与孔丘非君臣也，德友而已矣！",tone:"德友",guide:"全段最后，鲁哀公对闵子说的这句话，是整段最动人的收尾：一个国君，在听了孔子讲述哀骀它之后，突然意识到自己与孔子的关系，不是君臣，而是德友。这是哀骀它的故事，在鲁哀公身上引发的涟漪：当一个人真正理解了「才全而德不形」，他看待一切关系的方式，都会改变。不再是君臣，不再是上下，只是两个在德性上相遇的人——德友。"}]}),i[19]||(i[19]=n("h2",{id:"五、闉跂支离无脣·德有余而形不足可忘",tabindex:"-1"},[e("五、闉跂支离无脣·德有余而形不足可忘 "),n("a",{class:"header-anchor",href:"#五、闉跂支离无脣·德有余而形不足可忘","aria-label":'Permalink to "五、闉跂支离无脣·德有余而形不足可忘"'},"​")],-1)),i[20]||(i[20]=n("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:p,glossary:x,"default-mode":"classic","aria-label":"德充符·闉跂支离 原文"}),i[21]||(i[21]=n("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"闉跂",pinyin:["yīn","qí"],meaning:"跛足、行走不便。闉跂支离无脣：虚构人物名，极言形体残缺之甚。"},{term:"支离",pinyin:["zhī","lí"],meaning:"身体残缺散乱。与「闉跂」「无脣」合为人名，象征形残而德全。"},{term:"无脣",pinyin:["wú","chún"],meaning:"没有嘴唇。闉跂支离无脣：极言形体残缺之甚。"},{term:"说卫灵公",pinyin:["shuì","wèi","líng","gōng"],meaning:"游说卫灵公。说：游说、进言。"},{term:"灵公说之",pinyin:["líng","gōng","yuè","zhī"],meaning:"卫灵公喜欢他（被他折服）。说：通「悦」，喜欢、欣赏。"},{term:"其脰肩肩",pinyin:["qí","dòu","jiān","jiān"],meaning:"再看那些形体完整的人，反而觉得他们的脖子细得像肩膀一样（显得渺小）。脰：脖子。"},{term:"甕㼜大瘿",pinyin:["wèng","yǔ","dà","yǐng"],meaning:"人名，虚构人物。甕㼜：大肚子（形如瓮罐）；大瘿：颈部长有巨大肿瘤。"},{term:"德有所长",pinyin:["dé","yǒu","suǒ","cháng"],meaning:"德性有所超越。德有所长而形有所忘：德的光芒充盈，形体自然退到背景。"},{term:"诚忘",pinyin:["chéng","wàng"],meaning:"真正的遗忘，指本末倒置的迷失：不忘该忘的（形体），却忘不该忘的（德性）。"}]}),i[22]||(i[22]=n("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(g,{title:"德有所长而形有所忘",subtitle:"当德性的光芒充盈到一定程度，形体自然退到了背景里。",lines:[{text:"灵公说之，而视全人：其脰肩肩。",tone:"反观",guide:"这个细节，是庄子最辛辣的一笔：卫灵公被闉跂支离无脣折服之后，再看那些形体完整的人——反而觉得他们的脖子细得像肩膀一样，显得渺小单薄。这不是说形体完整的人真的变小了，而是说：当德性充盈的人出现，形体的标准就失效了。原来以为形体完整才是「完整」，见到真正德充的人之后，才发现：那些形体完整却德性空洞的人，才是真正的残缺。"},{text:"德有所长而形有所忘。",tone:"核心",guide:"这是第五段的核心句，也是《德充符》全篇命题的最简洁表达：德性有所超越，形体的缺陷就被遗忘了。不是别人假装看不见，不是刻意去忽略，而是德性的光芒充盈到一定程度，形体自然退到了背景里——就像太阳出来，灯光自然黯淡，不需要刻意熄灭。"},{text:"人不忘其所忘而忘其所不忘，此谓诚忘。",tone:"诚忘",guide:"这是全段最深刻的一句反讽：所忘（应该忘记的）——外在形体、身份、地位；所不忘（不应该忘记的）——内在德性、生命本质。人们偏偏把该忘的（形体）牢牢记住，却把不该忘的（德性）彻底遗忘——这才叫「诚忘」，真正的遗忘，真正的迷失。子产忘不了申徒嘉的断足，孔子忘不了叔山无趾的受刑经历，世人忘不了哀骀它的丑陋——这些，都是「诚忘」。"},{text:"圣人不谋，恶用知？不斵，恶用胶？无丧，恶用德？不货，恶用商？",tone:"四问",guide:"这四句排比，是庄子对「人为努力」最彻底的解构：智谋（知）的存在前提是有问题需要解决——圣人不谋划，不需要智谋；契约（胶）的前提是有冲突需要约束——圣人不强行改变，不需要契约；德行（德）的前提是有失去需要弥补——圣人本性完整无丧，不需要刻意德行；商业（商）的前提是有需求需要交换——圣人不以技艺谋利，不需要商业手段。这四种东西，本来都是天然的（天鬻）——是人把它们变成了工具、手段、买卖。圣人回到天然的状态，这四种工具就都用不上了。"},{text:"有人之形，无人之情。有人之形，故群于人；无人之情，故是非不得于身。",tone:"有形无情",guide:"这是第五段的终极命题，也是第六段「无情之辩」的直接引子：有人之形——有人的外在形体，所以能与人群居，融入人间；无人之情——没有人的好恶执着，所以是非无法附着在他身上。这里的「情」，不是情感，而是好恶的执着、是非的判断——那种让人内耗、让人被世俗是非所伤的东西。"}]}),i[23]||(i[23]=n("h2",{id:"六、庄惠之辩·无情·常因自然",tabindex:"-1"},[e("六、庄惠之辩·无情·常因自然 "),n("a",{class:"header-anchor",href:"#六、庄惠之辩·无情·常因自然","aria-label":'Permalink to "六、庄惠之辩·无情·常因自然"'},"​")],-1)),i[24]||(i[24]=n("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:z,glossary:b,"default-mode":"classic","aria-label":"德充符·庄惠之辩 原文"}),i[25]||(i[25]=n("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"惠子",pinyin:["huì","zǐ"],meaning:"惠施，战国时期名家代表人物，庄子的挚友兼论辩对手。以「坚白论」「合同异」等名辩著称。"},{term:"无情",pinyin:["wú","qíng"],meaning:"庄子重新定义：不是没有情感，而是不以好恶内伤其身，常因自然而不益生。"},{term:"好恶",pinyin:["hào","è"],meaning:"喜好与厌恶，即情感的执着。不以好恶内伤其身：不用好恶来伤害自己的内心。"},{term:"益生",pinyin:["yì","shēng"],meaning:"人为地增添、强化生命。常因自然而不益生：顺应自然，不刻意经营生命。"},{term:"坚白",pinyin:["jiān","bái"],meaning:"惠施著名的名辩命题「坚白石」（坚与白是否可以分离）。天选子之形，子以坚白鸣：天给了你这副身体，你却用它做消耗自己的事。"}]}),i[26]||(i[26]=n("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(g,{title:"生命不需要增益，只需要不被消耗",subtitle:"道与天已经给了你一切——你只需要停止破坏它。",lines:[{text:"惠子谓庄子曰：人故无情乎？庄子曰：然。",tone:"一个字",guide:"这段辩论，从庄子一个字的回答开始——「然」。庄子没有解释，没有铺垫，直接承认：是的，人没有情。这个「然」字，是庄子故意设的陷阱：他知道惠施会追问，他要借惠施的追问，把「情」这个概念重新定义。"},{text:"道与之貌，天与之形，恶得不谓之人？",tone:"定义",guide:"惠施问：没有情感，怎么还叫人？庄子答：道给了他面貌，天给了他形体——这就是人。庄子把「人」的定义，从「有情感」换成了「道与天的赋予」。这个替换极为关键：惠施的「人」是有情感的生物（儒家·名家的定义），庄子的「人」是道与天所赋予的存在（道家的定义）。两人说的「人」，根本不是同一个概念。这是庄惠之辩的根本分歧所在。"},{text:"吾所谓无情者，言人之不以好恶内伤其身，常因自然而不益生也。",tone:"定义",guide:"这是《德充符》全篇最重要的一句定义，也是庄子对「无情」最完整的解释：我说的「无情」，不是没有情感，而是不用好恶来伤害自己的内心，常常顺应自然，不人为地增益生命。两个层次：消极层面——不以好恶内伤其身，不让情感的执着从内部伤害自己；积极层面——常因自然而不益生，顺应自然，不刻意经营、强化生命。「无情」不是冷漠，不是麻木，而是不让情感的好恶，成为消耗生命的力量。"},{text:"道与之貌，天与之形，无以好恶内伤其身。",tone:"终极",guide:"庄子的终极回答，极为简洁：道已经给了你面貌，天已经给了你形体——你只需要做一件事：不用好恶来伤害它。不是「努力保全」，不是「刻意养生」，而是停止破坏——道与天给你的已经足够，你只需要不去损耗它。这是庄子最深的生命观：生命不需要增益，只需要不被消耗。"},{text:"今子外乎子之神，劳乎子之精，倚树而吟，据槁梧而瞑。天选子之形，子以坚白鸣。",tone:"警醒",guide:"这是全篇最后一句话，也是庄子对惠施最深的悲悯与讽刺：你把精神放逐到外面（外乎子之神），劳损你的精气（劳乎子之精），靠着树吟咏，靠着枯槁的梧桐打盹——这是惠施的日常：沉迷于名辩，耗尽精神，形容枯槁。天选择了你的形体——你却用它来鸣叫「坚白论」。庄子没有愤怒，没有鄙视，只是平静地说出这个事实：惠施，你正在用道与天赋予你的生命，去做那些消耗它的事。这就是「以好恶内伤其身」的活生生的例子——不是别人，正是庄子最亲密的论辩挚友。"}]}),i[27]||(i[27]=f("",50))])}}});export{C as __pageData,D as default};
